window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['engineer-2021-1']={"round":"2021-1","cert":"engineer","questions":[{"id":"13679","number":1,"category":"소프트웨어 설계","type":"choice","subject":"운영체제 분석을 위해 리눅스에서 버전을 확인하고자 할 때 사용되는 명령어는?","choices":[{"n":1,"html":"ls"},{"n":2,"html":"hostname"},{"n":3,"html":"pwd"},{"n":4,"html":"uname"}],"answer":[4],"wiki":[{"title":"리눅스 ls","url":"https://itwiki.kr/w/리눅스 ls"},{"title":"리눅스 uname","url":"https://itwiki.kr/w/리눅스 uname"},{"title":"리눅스 pwd","url":"https://itwiki.kr/w/리눅스 pwd"}],"explain":{"ai":["<p>리눅스에서 운영체제 버전을 확인하고자 할 때 사용되는 명령어는 uname입니다. \nuname 명령어는 시스템 정보를 출력하는 명령어로, 운영체제의 이름, 호스트 이름, 커널 버전 등 다양한 정보를 출력할 수 있습니다. \n리눅스 시스템에서 uname 명령어를 사용하면 운영체제의 버전을 확인할 수 있습니다. \n따라서 uname 명령어는 운영체제 분석을 위해 리눅스에서 버전을 확인하고자 할 때 사용되는 적절한 명령어입니다. \n다른 명령어인 ls, hostname, pwd는 각각 다른 용도로 사용되며, 운영체제 버전을 확인하는 데는 적합하지 않습니다. \nls는 파일 목록을 출력하는 명령어, hostname은 호스트 이름을 출력하는 명령어, pwd는 현재 작업 디렉토리를 출력하는 명령어입니다. \n이러한 명령어들은 운영체제 버전을 확인하는 데 사용할 수 없습니다. \n따라서 uname 명령어를 사용하여 리눅스에서 운영체제 버전을 확인할 수 있습니다.</p>"]}},{"id":"13680","number":2,"category":"소프트웨어 설계","type":"choice","subject":"통신을 위한 프로그램을 생성하여 포트를 할당하고, 클라이언트의 통신 요청 시 클라이언트와 연결하는 내·외부 송·수신 연계기술은?","choices":[{"n":1,"html":"DB링크 기술"},{"n":2,"html":"소켓 기술"},{"n":3,"html":"스크럼 기술"},{"n":4,"html":"프로토타입 기술"}],"answer":[2],"explain":{"ai":["<p>통신 프로그램을 생성하고 클라이언트의 통신 요청에 응답하여 연결하는 기술은 소켓 기술입니다. 소켓 기술은 네트워크를 통해 데이터를 송수신하는 데 사용됩니다. 클라이언트와 서버가 서로 통신하려면 양쪽 모두 소켓을 생성하고 연결해야 합니다. 소켓 기술은 TCP/IP 프로토콜을 사용하여 데이터를 전송하며, 포트 번호를 통해 통신을 위한 경로를 설정합니다. 따라서 소켓 기술은 통신을 위한 내·외부 송·수신 연계기술입니다. 다른 옵션은 소켓 기술과 관련이 없으므로 정답은 소켓 기술입니다.</p>"]}},{"id":"13681","number":3,"category":"소프트웨어 설계","type":"choice","subject":"객체지향 개념에서 연관된 데이터와 함수를 함께 묶어 외부와 경계를 만들고 필요한 인터페이스만을 밖으로 드러내는 과정은?","choices":[{"n":1,"html":"메시지(Message)"},{"n":2,"html":"캡슐화(Encapsulation)"},{"n":3,"html":"다형성(Polymorphism)"},{"n":4,"html":"상속(Inheritance)"}],"answer":[2],"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"explain":{"ai":["<p>객체지향 프로그래밍에서 데이터와 함수를 하나의 단위로 묶는 것을 말한다. \n이 때 외부와의 상호작용을 최소화하고, 필요한 기능만 외부에 노출 시키는데 이句话의 핵심은 데이터와 함수를 하나의 단위로 묶고 외부에 필요한 부분만 노출시키는 것이다. \n즉, 객체 내부의 데이터를 외부에서 직접 접근하지 못하게 하고, 함수를 통해서만 접근할 수 있도록 한다. \n이러한 특성을 통해 객체의 내부 구현을 숨기고, 외부와의 상호작용을 제한함으로써 프로그램의 안정성과 재사용성을提高할 수 있다. \n따라서 이 질문의 답은 캡슐화이다.</p>"]}},{"id":"13682","number":4,"category":"소프트웨어 설계","type":"choice","subject":"GoF(Gangs of Four) 디자인 패턴의 생성패턴에 속하지 않는 것은?","choices":[{"n":1,"html":"추상 팩토리(Abstract Factory)"},{"n":2,"html":"빌더(Builder)"},{"n":3,"html":"어댑터(Adapter)"},{"n":4,"html":"싱글턴(Singleton)"}],"answer":[3],"explain":{"ai":["<p>GoF 디자인 패턴의 생성 패턴은 객체의 생성과 관련이 있는 패턴으로, 객체의 생성을 캡슐화하여 객체 생성의 유연함을 높이는 것을 목적으로 한다. </p>\n<p>추상 팩토리, 빌더, 싱글턴 패턴은 모두 객체의 생성과 관련이 있기 때문에 생성 패턴에 속한다. </p>\n<p>반면에 어댑터 패턴은 기존에 생성된 객체의 인터페이스를 변경하여 재사용할 수 있도록 도와주는 패턴으로, 생성 패턴에 속하지 않는다. 어댑터 패턴은 구조 패턴에 속한다. </p>\n<p>따라서 GoF 디자인 패턴의 생성 패턴에 속하지 않는 것은 어댑터 패턴이다.</p>"]}},{"id":"13683","number":5,"category":"소프트웨어 설계","type":"choice","subject":"응용프로그램의 프로시저를 사용하여 원격 프로시저를 로컬 프로시저처럼 호출하는 방식의 미들웨어는?","choices":[{"n":1,"html":"WAS(Web Application Server)"},{"n":2,"html":"MOM(Message Oriented Middleware)"},{"n":3,"html":"RPC(Remote Procedure Call)"},{"n":4,"html":"ORB(Object Request Broker)"}],"answer":[3],"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"explain":{"ai":["<p>원격 프로시저를 로컬처럼 호출하는 방식의 미들웨어는 RPC이다. RPC는 응용 프로그램의 프로시저를 사용하여 원격 프로시저를 로컬 프로시저처럼 호출하는 방식의 미들웨어다.이를 통해 분산 환경에서 프로시저를 호출할 수 있다. RPC는 클라이언트와 서버 사이의 통신을 간단하게 해주고, 원격 프로시저 호출을 지원한다. </p>\n<p>RPC를 사용하면 개발자가 복잡한 네트워크 통신을 직접 처리할 필요가 없어서 개발이 쉬워진다. 또한 RPC를 사용하면 원격 프로시저를 로컬 프로시저처럼 호출할 수 있기 때문에 코드를 더 쉽게 작성할 수 있다. </p>\n<p>결론적으로 RPC는 원격 프로시저를 로컬 프로시저처럼 호출하는 방식의 미들웨어로, 분산 환경에서 프로시저를 호출할 수 있는 중요한 기술이다.</p>"]}},{"id":"13684","number":6,"category":"소프트웨어 설계","type":"choice","subject":"바람직한 소프트웨어 설계 지침이 아닌 것은?","choices":[{"n":1,"html":"모듈의 기능을 예측할 수 있도록 정의한다."},{"n":2,"html":"이식성을 고려한다."},{"n":3,"html":"적당한 모듈의 크기를 유지한다."},{"n":4,"html":"가능한 모듈을 독립적으로 생성하고 결합도를 최대화한다."}],"answer":[4],"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"},{"title":"응집도","url":"https://itwiki.kr/w/응집도"},{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"explain":{"ai":["<p>바람직한 소프트웨어 설계 지침은 모듈의 재사용성, 이식성, 유지보수성 등을 고려하여 설계해야 한다. 모듈의 기능을 예측할 수 있도록 정의하고, 이식성을 고려하며, 적당한 모듈의 크기를 유지하는 것은 모두 좋은 설계 지침이다. 하지만 가능한 모듈을 독립적으로 생성하고 결합도를 최대화하는 것은 좋은 설계 지침이 아니다. 결합도는 모듈之间의 상호 의존성을 말하며, 높은 결합도는 모듈의 재사용성과 유지보수성을 낮추게 된다. 따라서 좋은 설계 지침은 결합도를 최소화하는 것이지 최대화하는 것이 아니다.</p>"]}},{"id":"13685","number":7,"category":"소프트웨어 설계","type":"choice","subject":"객체지향 분석 방법론 중 Coad-Yourdon 방법에 해당하는 것은?","choices":[{"n":1,"html":"E-R 다이어그램을 사용하여 객체의 행위를 데이터 모델링하는데 초점을 둔 방법이다."},{"n":2,"html":"객체, 동적, 기능 모델로 나누어 수행하는 방법이다."},{"n":3,"html":"미시적 개발 프로세스와 거시적 개발 프로세스를 모두 사용하는 방법이다."},{"n":4,"html":"Use-Case를 강조하여 사용하는 방법이다."}],"answer":[1],"explain":{"ai":["<p>Coad-Yourdon 방법은 객체지향 분석 방법론 중 하나로 E-R 다이어그램을 사용하여 객체의 행위를 데이터 모델링하는데 초점을 둔 방법이다. 이 방법은 객체의 속성과 행위를 분석하여 객체 모델을 생성하는 것을 주 목적으로 한다. 따라서 Coad-Yourdon 방법은 데이터 모델링을 강조하며 E-R 다이어그램을 사용하여 객체의 행위를 모델링한다. 이는 다른 객체지향 분석 방법론과는 다소 차별화되는 특징이다. </p>\n<p>이 방법은 주로 데이터 중심의 객체지향 분석에 사용되며 객체의 데이터 구조와 행위를 명확하게 모델링하는 데 도움을 준다. 따라서 정답은 1번이다. </p>\n<p>다른 방법론들은 각기 다른 특징을 가지고 있다. 예를 들어 2번의 방법은 객체, 동적, 기능 모델로 나누어 수행하는 방법이고 3번은 미시적 개발 프로세스와 거시적 개발 프로세스를 모두 사용하는 방법이다. 4번은 Use-Case를 강조하여 사용하는 방법이다. </p>\n<p>하지만 Coad-Yourdon 방법은 E-R 다이어그램을 사용하여 데이터 모델링에 초점을 두는 특징이 있다.</p>"]}},{"id":"13686","number":8,"category":"소프트웨어 설계","type":"choice","subject":"다음은 어떤 프로그램 구조를 나타낸다. 모듈 F에서의 fan-in과 fan-out의 수는 얼마인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"fan-in : 2, fan-out : 3"},{"n":2,"html":"fan-in : 3, fan-out : 2"},{"n":3,"html":"fan-in : 1, fan-out : 2"},{"n":4,"html":"fan-in : 2, fan-out : 1"}],"answer":[2]},{"id":"13687","number":9,"category":"소프트웨어 설계","type":"choice","subject":"현행 시스템 분석에서 고려하지 않아도 되는 항목은?","choices":[{"n":1,"html":"DBMS 분석"},{"n":2,"html":"네트워크 분석"},{"n":3,"html":"운영체제 분석"},{"n":4,"html":"인적 자원 분석"}],"answer":[4],"explain":{"ai":["<p>현행 시스템 분석은 기존 시스템의 구성과 기능을 분석하여 종합적인 이해를 도모하는 것을 의미한다. 이过程에서 고려해야 하는 항목으로는 DBMS 분석, 네트워크 분석, 운영체제 분석 등이 있다. </p>\n<p>인적 자원 분석은 시스템 구축에 필요한 인력 및 훈련과 관련이 있다. 하지만 현행 시스템을 분석할 때는 주로 기술적인 측면에 초점을 맞추기 때문에 인적 자원과는 직접적으로 관련이 없다. </p>\n<p>따라서 현행 시스템 분석에서 고려하지 않아도 되는 항목은 인적 자원 분석이다.</p>"]}},{"id":"13688","number":10,"category":"소프트웨어 설계","type":"choice","subject":"분산 컴퓨팅 환경에서 서로 다른 기종 간의 하드웨어나 프로토콜, 통신환경 등을 연결하여 응용프로그램과 운영환경 간에 원만한 통신이 이루어질 수 있게 서비스를 제공하는 소프트웨어는?","choices":[{"n":1,"html":"미들웨어"},{"n":2,"html":"하드웨어"},{"n":3,"html":"오픈허브웨어"},{"n":4,"html":"그레이웨어"}],"answer":[1],"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"explain":{"ai":["<p>분산 컴퓨팅 환경에서 서로 다른 기종의 하드웨어나 프로토콜, 통신 환경 등을 연결하여 응용 프로그램과 운영 환경 간의 원만한 통신을 이끌어낼 수 있게 하는 소프트웨어는 미들웨어입니다. 미들웨어는 과거에는 운영체제와 응용 프로그램 사이에서 데이터를 주고받을 때 필요한 통신 처리나 데이터 변환 등의 역할을 انجام했습니다. 그러나現在는 데이터베이스 관리나 메시지 패싱 등 다양한 기능을 제공하는 소프트웨어로 발전했습니다. 종류도 molto 다양해져서 웹 미들웨어, 데이터베이스 미들웨어,essage 미들웨어 등으로 구분되기도 합니다. 이러한 미들웨어의 역할 덕분에 서로 다른 시스템이나 플랫폼 간의 통신과 상호 운용이 가능해졌습니다. </p>\n<p>미들웨어는 응용 프로그램과 운영 환경 간의 인터페이스 역할을 하기 때문에 분산 컴퓨팅 환경에서 매우 중요한 역할을 합니다. 이를 통해 개발자들은 서로 다른 시스템이나 플랫폼에서 운영되는 응용 프로그램之间의 상호 운용성을 높일 수 있습니다. Además, 미들웨어는 보안이나 성능 최적화 등과 같은 추가적인 기능들을 제공할 수 있습니다. </p>\n<p>따라서, 이러한 설명을 종합해 볼 때 분산 컴퓨팅 환경에서 서로 다른 기종의 하드웨어나 프로토콜, 통신 환경 등을 연결하여 응용 프로그램과 운영 환경 간의 원만한 통신을 제공하는 소프트웨어는 미들웨어라는 결론에 도달합니다.</p>"]}},{"id":"13689","number":11,"category":"소프트웨어 설계","type":"choice","subject":"CASE(Computer Aided Software Engineering)에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"소프트웨어 모듈의 재사용성이 향상된다."},{"n":2,"html":"자동화된 기법을 통해 소프트웨어 품질이 향상된다."},{"n":3,"html":"소프트웨어 사용자들에게 사용 방법을 신속히 숙지시키기 위해 사용된다."},{"n":4,"html":"소프트웨어 유지보수를 간편하게 수행할 수 있다."}],"answer":[3],"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"explain":{"ai":["<p>CASE는 컴퓨터를 이용한 소프트웨어 공학을 의미한다. 이는 소프트웨어开发을 자동화하거나 지원하는 도구와 기법을 제공함으로써 소프트웨어의 품질을 향상하고 개발 시간을 단축하는 것을 목표로 한다. </p>\n<p>CASE를 사용하면 소프트웨어 모듈의 재사용성이 향상되고, 자동화된 기법을 통해 소프트웨어 품질이 향상된다. 또한 소프트웨어 mantenace를 간편하게 수행할 수 있다. </p>\n<p>그러나 CASE는 소프트웨어 사용자들에게 사용 방법을 신속히 숙지시키기 위한 도구가 아니다. 이는 주로 소프트웨어 개발 과정에서 개발자们을 unterstütz기 위한 도구이다. </p>\n<p>따라서 정답은 3번이다. 이는 CASE의 주된 목적과 기능을 잘 설명하고 있지 않다.</p>"]}},{"id":"13690","number":12,"category":"소프트웨어 설계","type":"choice","subject":"UML(Unified Modeling Language)에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"기능적 모델은 사용자 측면에서 본 시스템 기능이며, UML에서는 Use case Diagram을 사용한다."},{"n":2,"html":"정적 모델은 객체, 속성, 연관관계, 오퍼레이션의 시스템의 구조를 나타내며, UML에서는 Class Diagram을 사용한다."},{"n":3,"html":"동적 모델은 시스템의 내부 동작을 말하며, UML에서는 Sequence Diagram, State Diagram, Activity Diagram을 사용한다."},{"n":4,"html":"State Diagram은 객체들 사이의 메시지 교환을 나타내며, Sequence Diagram은 하나의 객체가 가진 상태와 그 상태의 변화에 의한 동작순서를 나타낸다."}],"answer":[4],"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"explain":{"ai":["<p>UML은 시스템을 모델링하는 데 사용되는 언어입니다. 기능적 모델, 정적 모델, 동적 모델로 나눌 수 있습니다. 기능적 모델은 시스템의 기능을 사용자 관점에서 나타내는 것으로 Use case Diagram을 사용합니다. 정적 모델은 시스템의 구조를 나타내는 것으로 Class Diagram을 사용합니다. 동적 모델은 시스템의 내부 동작을 나타내는 것으로 Sequence Diagram, State Diagram, Activity Diagram 등을 사용합니다.</p>\n<p>State Diagram은 하나의 객체가 가지는 상태와 상태의 변화를 나타내며, Sequence Diagram은 객체들 사이의 메시지 교환을 나타냅니다. 그러므로 4번이 틀린 설명입니다. Sequence Diagram은 메시지 교환을 나타내고 State Diagram은 상태와 상태 변화에 의한 동작 순서를 나타냅니다.</p>"]}},{"id":"13691","number":13,"category":"소프트웨어 설계","type":"choice","subject":"기본 유스케이스 수행 시 특별한 조건을 만족할 때 수행하는 유스케이스는?","choices":[{"n":1,"html":"연관"},{"n":2,"html":"확장"},{"n":3,"html":"선택"},{"n":4,"html":"특화"}],"answer":[2],"explain":{"ai":["<p>기본 유스케이스 수행 시 특별한 조건을 만족할 때 수행하는 유스케이스를 알아보자. 이 경우 주로 기본 유스케이스에 추가적인 기능이나 조건을 더해 수행하는 유스케이스를 말한다. </p>\n<p>여기서 기본 유스케이스에 확장된 기능을 제공하는 유스케이스를 말하는데 이는 특별한 조건이 만족되면 기본 유스케이스에 추가적으로 수행되는 것을 의미한다. </p>\n<p>따라서 특별한 조건을 만족할 때 수행하는 유스케이스는 확장 유스케이스라고 하며 이는 2번에 해당한다.</p>"]}},{"id":"13692","number":14,"category":"소프트웨어 설계","type":"choice","subject":"다음 중 요구사항 모델링에 활용되지 않는 것은?","choices":[{"n":1,"html":"애자일(Agile) 방법"},{"n":2,"html":"유스케이스 다이어그램(Use Case Diagram)"},{"n":3,"html":"시컨스 다이어그램(Sequence Diagram)"},{"n":4,"html":"단계 다이어그램(Phase Diagram)"}],"answer":[4],"wiki":[{"title":"시퀀스 다이어그램","url":"https://itwiki.kr/w/시퀀스 다이어그램"},{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"},{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"explain":{"ai":["<p>요구사항 모델링은 시스템의 요구사항을 분석하고 모델링하는 과정입니다. \n애자일 방법은 요구사항 모델링에 활용될 수 있습니다. \n유스케이스 다이어그램과 시컨스 다이어그램은 요구사항 모델링에 일반적으로 사용되는 다이어그램입니다. \n반면에 단계 다이어그램은 주로 프로세스 또는 시스템의 전개 과정을 보여주는 것으로 요구사항 모델링에 직접 활용되지는 않습니다. \n따라서 단계 다이어그램은 요구사항 모델링에 활용되지 않는 것입니다.</p>"]}},{"id":"13693","number":15,"category":"소프트웨어 설계","type":"choice","subject":"디자인 패턴을 이용한 소프트웨어 재사용으로 얻어지는 장점이 아닌 것은?","choices":[{"n":1,"html":"소프트웨어 코드의 품질을 향상시킬 수 있다."},{"n":2,"html":"개발 프로세스를 무시할 수 있다."},{"n":3,"html":"개발자들 사이의 의사소통을 원활하게 할 수 있다."},{"n":4,"html":"소프트웨어의 품질과 생산성을 향상시킬 수 있다."}],"answer":[2],"wiki":[{"title":"소프트웨어 재사용","url":"https://itwiki.kr/w/소프트웨어 재사용"}],"explain":{"ai":["<p>디자인 패턴을 이용한 소프트웨어 재사용은 여러 가지 장점을 제공합니다. 먼저, 소프트웨어 코드의 품질을 향상시킬 수 있습니다. 또한 개발자들 사이의 의사소통을 원활하게 할 수 있고 소프트웨어의 품질과生产성을 향상시킬 수 있습니다. </p>\n<p>그러나 개발 프로세스를 무시할 수 있다고 말할 수는 없습니다. 디자인 패턴은 개발 프로세스를 더 체계적이고 효율적으로 만들기 위한 도구입니다. 개발 프로세스를 무시하면 오히려 코드의 품질이 나빠지고 개발 시간이 길어질 수 있습니다. </p>\n<p>따라서 디자인 패턴을 이용한 소프트웨어 재사용의 장점이 아닌 것은 개발 프로세스를 무시할 수 있다는 것입니다.</p>"]}},{"id":"13694","number":16,"category":"소프트웨어 설계","type":"choice","subject":"럼바우(Rumbaugh) 분석기법에서 정보모델링이라고도 하며, 시스템에서 요구되는 객체를 찾아내어 속성과 연산 식별 및 객체들 간의 관계를 규정하여 다이어그램을 표시하는 모델링은?","choices":[{"n":1,"html":"Object"},{"n":2,"html":"Dynamic"},{"n":3,"html":"Function"},{"n":4,"html":"Static"}],"answer":[1],"wiki":[{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"explain":{"ai":["<p>럼바우 분석기법에서 정보모델링은 시스템에서 요구되는 객체를 찾아내어 속성과 연산을 식별하고 객체들 간의 관계를 규정하여 다이어그램을 표시하는 모델링입니다. \n이 모델링은 객체 모델링이라고도 하며 시스템의 구조와 행동을 이해하기 위해 객체와 그 객체들 간의 관계를 정의합니다.\n럼바우 분석기법의 객체 모델링은 시스템의 요구사항을 분석하고 이해하기 위한 중요한 단계로 시스템의 복잡성을 단순화하고 명확화하는 데 도움이 됩니다.\n따라서 정답은 객체 모델링을 의미하는 1번입니다.</p>"]}},{"id":"13695","number":17,"category":"소프트웨어 설계","type":"choice","subject":"소프트웨어를 개발하기 위한 비즈니스(업무)를 객체와 속성, 클래스와 멤버, 전체와 부분 등으로 나누어서 분석해 내는 기법은?","choices":[{"n":1,"html":"객체지향 분석"},{"n":2,"html":"구조적 분석"},{"n":3,"html":"기능적 분석"},{"n":4,"html":"실시간 분석"}],"answer":[1],"explain":{"ai":["<p>소프트웨어를 개발하기 위한 비즈니스 또는 업무를 분석하는 기법 중에서 객체와 속성, 클래스와 멤버, 전체와 부분 등으로 나누어 분석하는 방법은 객체지향 분석입니다. 이 기법은 실세계의 사물이나 요구사항을 객체로 모델링하고 객체간의 관계를 정의하여 소프트웨어를 설계합니다. 따라서 소프트웨어 개발을 위해 비즈니스 또는 업무를 객체와 속성, 클래스와 멤버, 전체와 부분으로 나누어 분석하는 기법은 객체지향 분석입니다.</p>"]}},{"id":"13696","number":18,"category":"소프트웨어 설계","type":"choice","subject":"애자일 소프트웨어 개발 기법의 가치가 아닌 것은?","choices":[{"n":1,"html":"프로세스의 도구보다는 개인과 상호작용에 더 가치를 둔다."},{"n":2,"html":"계약 협상보다는 고객과의 협업에 더 가치를 둔다."},{"n":3,"html":"실제 작동하는 소프트웨어보다는 이해하기 좋은 문서에 더 가치를 둔다."},{"n":4,"html":"계획을 따르기보다는 변화에 대응하는 것에 더 가치를 둔다."}],"answer":[3],"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"explain":{"ai":["<p>애자일 소프트웨어 개발 기법은 빠른变化에 대응하고 고객의需求을 만족시키는 것을 목표로 한다. 애자일의 핵심 가치는 개인과 상호작용, 고객과의 협업, 실제 작동하는 소프트웨어, 변화에 대한 대응能力이다. </p>\n<p>보기 중 3번은 애자일의 가치와 반대된다. 애자일은 문서보다는 실제 작동하는 소프트웨어에 더 가치를 둔다. 즉, 문서보다 소프트웨어가 작동하는지에 더 관심이 있다. 문서는 부차적으로 소프트웨어 개발을 지원하는 것이지 핵심이 아니다. </p>\n<p>따라서 3번이 애자일 소프트웨어 개발 기법의 가치가 아니다.</p>"]}},{"id":"13697","number":19,"category":"소프트웨어 설계","type":"choice","subject":"UML 다이어그램 중 시스템 내 클래스의 정적 구조를 표현하고 클래스와 클래스, 클래스의 속성 사이의 관계를 나타내는 것은?","choices":[{"n":1,"html":"Activity Diagram"},{"n":2,"html":"Modea Diagram"},{"n":3,"html":"State Diagram"},{"n":4,"html":"Class Diagram"}],"answer":[4],"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"explain":{"ai":["<p>UML 다이어그램은 시스템을 모델링하기 위한 도구입니다. 시스템 내 클래스의 정적 구조를 표현하고 클래스와 클래스, 클래스의 속성 사이의 관계를 나타내는 다이어그램은 클래스 다이어그램입니다. 클래스 다이어그램은 클래스와 클래스 간의 관계, 즉 상속, 연관, 구성, 의존 관계를แสดง합니다. 또한 클래스의 속성과 연산도 표기합니다. 따라서 클래스 다이어그램은 시스템의 정적 구조를 명확하게 나타내는 데에는 매우 중요한 다이어그램입니다.</p>"]}},{"id":"13698","number":20,"category":"소프트웨어 설계","type":"choice","subject":"소프트웨어 설계시 제일 상위에 있는 main user function에서 시작하여 기능을 하위 기능들로 분할해 가면서 설계하는 방식은?","choices":[{"n":1,"html":"객체 지향 설계"},{"n":2,"html":"데이터 흐름 설계"},{"n":3,"html":"상향식 설계"},{"n":4,"html":"하향식 설계"}],"answer":[4],"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"}],"explain":{"ai":["<p>소프트웨어 설계시 제일 상위에 있는 주요 기능에서 시작하여 이를 하위 기능들로 분할해 가면서 설계하는 방식을 말한다. 이것은 전체적인 시스템의 구조와 기능을 먼저 정의하고, 이후에 이를 상세하게 분해하여 diseño하는 방법론이다.这种 설계 방법은 시스템의 전체적인 구조와 기능을 먼저 정의한 후, 이를 상세하게 분해하여 설계하는 방식이기 때문에, 전체 시스템의 구조와 흐름을 명확하게 이해하고 설계할 수 있다. 또한, sistemi의 각 구성 요소와 их 관계를 명확하게 정의하여, 시스템의 복잡성을 줄이고 유지 보수를 용이하게 할 수 있다. 따라서 제일 상위에 있는 주요 기능에서 시작하여 이를 하위 기능들로 분할해 가면서 설계하는 방식인 하향식 설계는 효과적인 소프트웨어 설계 방법이다.</p>"]}},{"id":"13699","number":21,"category":"소프트웨어 개발","type":"choice","subject":"구현 단계에서의 작업 절차를 순서에 맞게 나열한 것은?","extra":"<pre class=\"contents\">㉠ 코딩한다.\r\n㉡ 코딩작업을 계획한다.\r\n㉢ 코드를 테스트한다.\r\n㉣ 컴파일한다.</pre>","choices":[{"n":1,"html":"㉠-㉡-㉢-㉣"},{"n":2,"html":"㉡-㉠-㉣-㉢"},{"n":3,"html":"㉢-㉠-㉡-㉣"},{"n":4,"html":"㉣-㉡-㉠-㉢"}],"answer":[2],"explain":{"ai":["<p>구현 단계에서는 먼저 어떤 코드를 작성해야 하는지 계획해야 하므로 ㉡ 코딩작업을 계획한다가 먼저 옵니다. 계획을 마친 후에는 실제로 코드를 작성하므로 ㉠ 코딩한다가 다음 순서입니다. 코드 작성 후에는 작성한 코드가 올바르게 동작하는지 확인해야 하므로 컴파일을 합니다. 따라서 ㉣ 컴파일한다가 그 다음입니다. 컴파일까지 마쳤으면 코드가 제대로 동작하는지 확인해야 하므로 ㉢ 코드를 테스트한다가 마지막 순서입니다. 즉 구현 단계에서는 코딩 작업을 계획하고, 코딩을 수행하고, 컴파일을 수행하고, 코드 테스트를 수행하는 순으로 진행됩니다.</p>"]}},{"id":"13700","number":22,"category":"소프트웨어 개발","type":"choice","subject":"다음 자료에 대하여 “Selection Sort”를 사용하여 오름차순으로 정렬한 경우 PASS 3의 결과는?","extra":"<pre class=\"contents\">8, 3, 4, 9, 7</pre>","choices":[{"n":1,"html":"3, 4, 7, 9, 8"},{"n":2,"html":"3, 4, 8, 9, 7"},{"n":3,"html":"3, 8, 4, 9, 7"},{"n":4,"html":"3, 4, 7, 8, 9"}],"answer":[1],"wiki":[{"title":"선택 정렬","url":"https://itwiki.kr/w/선택 정렬"}],"explain":{"ai":["<p>Selection Sort는 배열에서 가장 작은 값을 선택하여 앞으로 이동시키는 정렬 알고리즘이다. </p>\n<p>PASS 1에서는 배열에서 가장 작은 값을 찾기 때문에 3을 선택하여 맨 앞으로 이동시킨다. \nPASS 2에서는 3을 제외한 나머지 배열을 대상으로 가장 작은 값을 찾기 때문에 4를 선택하여 두 번째 자리로 이동시킨다. \nPASS 3에서는 3과 4를 제외한 나머지 배열을 대상으로 가장 작은 값을 찾기 때문에 7을 선택하여 세 번째 자리로 이동시킨다. </p>\n<p>따라서 PASS 3의 결과는 3, 4, 7, 9, 8이 된다.</p>"]}},{"id":"13701","number":23,"category":"소프트웨어 개발","type":"choice","subject":"하향식 통합시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈은?","choices":[{"n":1,"html":"Stub"},{"n":2,"html":"Driver"},{"n":3,"html":"Procedure"},{"n":4,"html":"Function"}],"answer":[1],"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"explain":{"ai":["<p>하향식 통합시험은 프로그램의 상위 모듈에서 حافظ의 모듈로 내려가면서 통합하는 방식입니다. 이 때 일부 모듈이 아직 개발되지 않은 경우 이를 대신하기 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈이 필요합니다. 이러한 모듈을 Stub이라고 합니다. Stub은 필요한 입력을 받아서 예상된 출력을 반환하여 통합 시험을 위해 사용됩니다. 따라서 하향식 통합시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈은 Stub입니다.</p>"]}},{"id":"13702","number":24,"category":"소프트웨어 개발","type":"choice","subject":"다음 전위식(prefix)을 후위식(postfix)으로 옳게 표현한 것은?","extra":"<pre class=\"contents\">- / * A ＋ B C D E</pre>","choices":[{"n":1,"html":"A B C + D / * E -"},{"n":2,"html":"A B * C D / + E -"},{"n":3,"html":"A B * C + D / E -"},{"n":4,"html":"A B C + * D / E -"}],"answer":[4],"explain":{"ai":["<p>전위식은 연산자가 피연산자 앞에 위치하는 표현법이다. 후위식은 연산자가 피연산자 뒤에 위치하는 표현법이다. </p>\n<p>지정된 전위식은 - / * A ＋ B C D E이다. 이 식의 후위식으로의 변환은 다음과 같은 순서로 진행된다. </p>\n<ol>\n<li>연산자 우선순위에 따라 연산자를 분리한다. </li>\n<li>각 연산자와 피연산자를 후위식으로 순서를 맞춘다. </li>\n</ol>\n<p>지정된 전위식에서 연산자의 우선순위는 다음과 같다. \n-는 1순위, /와 *는 2순위, +는 3순위이다. </p>\n<p>우선순위를 고려하여 후위식으로 나타내면 A B C + * D / E -가 된다. </p>\n<p>따라서 전위식 - / * A ＋ B C D E를 후위식으로 옳게 표현한 것은 4번이다.</p>"]}},{"id":"13703","number":25,"category":"소프트웨어 개발","type":"choice","subject":"그래프의 특수한 형태로 노드(Node)와 선분(Branch)으로 되어 있고, 정점 사이에 사이클(Cycle)이 형성되어 있지 않으며, 자료 사이의 관계성이 계층 형식으로 나타나는 비선형 구조는?","choices":[{"n":1,"html":"tree"},{"n":2,"html":"network"},{"n":3,"html":"stack"},{"n":4,"html":"distributed"}],"answer":[1],"wiki":[{"title":"자료 구조","url":"https://itwiki.kr/w/자료 구조"},{"title":"비선형 자료 구조","url":"https://itwiki.kr/w/비선형 자료 구조"},{"title":"트리","url":"https://itwiki.kr/w/트리"}],"explain":{"ai":["<p>이 문제는 그래프의 특수한 형태인 트리 구조를 묻는 문제입니다. 트리 구조는 노드와 선분으로 구성되어 있으며, 사이클이不存在하고 자료 사이의 관계성이 계층 형식으로 나타나는 비선형 구조입니다. </p>\n<p>트리 구조의 특징은 다음과 같습니다.</p>\n<ul>\n<li>노드와 선분으로 구성</li>\n<li>사이클이不存在</li>\n<li>자료 사이의 관계성이 계층 형식으로 나타남</li>\n</ul>\n<p>이러한 특징을 만족하는 구조는 트리 구조이므로, 정답은 1번 트리 구조입니다. </p>\n<p>다음은 잘못된 선택지에 대한 설명입니다.</p>\n<ul>\n<li>2번 네트워크 구조는 사이클이 존재할 수 있으며, 계층 형식이 아닐 수 있습니다.</li>\n<li>3번 스택은 선형 구조로, Last In First Out(LIFO) 방식으로 자료를 처리합니다.</li>\n<li>4번 분산 구조는 여러개의 시스템이 연결되어 있는 구조로, 트리 구조와는 관련이 없습니다.</li>\n</ul>"]}},{"id":"13704","number":26,"category":"소프트웨어 개발","type":"choice","subject":"스택에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"입출력이 한쪽 끝으로만 제한된 리스트이다."},{"n":2,"html":"Head(front)와 Tail(rear)의 2개 포인터를 갖고 있다."},{"n":3,"html":"LIFO 구조이다."},{"n":4,"html":"더 이상 삭제할 데이터가 없는 상태에서 데이터를 삭제하면 언더플로(Underflow)가 발생한다."}],"answer":[2],"wiki":[{"title":"스택","url":"https://itwiki.kr/w/스택"}],"explain":{"ai":["<p>스택은 후입선출의 자료구조로, 입출력이 한쪽 끝으로만 제한된 리스트이기 때문에 1번과 3번은 맞다. 데이터가 있는 상태에서 삭제操作을 performed하고 더 이상 삭제할 데이터가 없는 상태에서 데이터를 삭제하면 언더플로가 발생하기 때문에 4번도 맞다. 일반적으로 스택은 한쪽 끝에서만 삽입이나 삭제가 이루어지므로 top 포인터를 사용한다. 스택에는 top 포인터만 있기 때문에 2번이 틀린 것이다.</p>"]}},{"id":"13705","number":27,"category":"소프트웨어 개발","type":"choice","subject":"디지털 저작권 관리(DRM)에 사용되는 기술요소가 아닌 것은?","choices":[{"n":1,"html":"키관리"},{"n":2,"html":"방화벽"},{"n":3,"html":"암호화"},{"n":4,"html":"크랙방지"}],"answer":[2],"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"explain":{"ai":["<p>디지털 저작권 관리 기술은 디지털 콘텐츠의 불법 복제나 배포를 방지하는 기술입니다. DRM의 주요 기술 요소에는 암호화, 키 관리, 크랙 방지 등이 있습니다. </p>\n<p>암호화는 콘텐츠를 암호화하여 불법적으로 접근하지 못하도록 합니다. 키 관리는 암호화 키를 생성하고 관리하는 기술입니다. 크랙 방지는 콘텐츠의 보안을 무력화시키는 크랙 등을 방지하는 기술입니다.</p>\n<p>방화벽은 네트워크 보안 기술의 일부로, 외부의 불법적인 접근을 막는 기술입니다. 하지만 방화벽은 콘텐츠 자체를 보호하는 기술이 아니라 네트워크의 보안을 유지하는 기술이기 때문에 디지털 저작권 관리 기술의 주요 요소는 아닙니다.</p>"]}},{"id":"13706","number":28,"category":"소프트웨어 개발","type":"choice","subject":"여러 개의 선택 항목 중 하나의 선택만 가능한 경우 사용하는 사용자 인터페이스(UI)요소는?","choices":[{"n":1,"html":"토글 버튼"},{"n":2,"html":"텍스트 박스"},{"n":3,"html":"라디오 버튼"},{"n":4,"html":"체크 박스"}],"answer":[3],"explain":{"ai":["<p>여러 개의 선택 항목 중 하나의 선택만 가능하게 하는 사용자 인터페이스 요소는 라디오 버튼이다. 라디오 버튼은 여러 개의 항목 중에서 한 개만을 선택할 수 있도록 되어 있다. 사용자는 여러 개의 라디오 버튼 중에서 원하는 항목을 클릭하여 선택할 수 있으며, 이미 선택된 항목을 다시 클릭하면 선택이 취소된다. 따라서 여러 개의 항목 중에서 하나의 항목만을 선택해야 하는 경우라면 라디오 버튼이 적절한 사용자 인터페이스 요소이다.</p>"]}},{"id":"13707","number":29,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어의 일부분을 다른 시스템에서 사용할 수 있는 정도를 의미하는 것은?","choices":[{"n":1,"html":"신뢰성(Reliability)"},{"n":2,"html":"유지보수성(Maintainability)"},{"n":3,"html":"가시성(Visibility)"},{"n":4,"html":"재사용성(Reusability)"}],"answer":[4],"explain":{"ai":["<p>소프트웨어의 일부분을 다른 시스템에서 사용할 수 있는 정도를 의미하는 것을 재사용성이라고 한다. 재사용성이란 한번 개발된 소프트웨어의 구성 요소를 다시 사용하여 다른 시스템에도 적용할 수 있는 정도를 의미한다. 즉, 한번 만들면 여러 곳에서 쓸 수 있는 모듈이나 컴포넌트를 개발할 때 महत하다. 신뢰성은 시스템이 고장나거나 오류가 발생했을 때 잘 복구되는지, 유지보수성은 시스템을 수정하거나 개선하기 쉽게 만드는 것이며, 가시성은 시스템의 내부 구조나 동작을 쉽게 понять 수 있는 정도를 의미한다.</p>"]}},{"id":"13708","number":30,"category":"소프트웨어 개발","type":"choice","subject":"자료구조에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"큐는 비선형구조에 해당한다."},{"n":2,"html":"큐는 First In – First Out 처리를 수행한다."},{"n":3,"html":"스택은 Last In – First out 처리를 수행한다."},{"n":4,"html":"스택은 서브루틴 호출, 인터럽트 처리, 수식 계산 및 수식 표기법에 응용된다."}],"answer":[1],"wiki":[{"title":"자료 구조","url":"https://itwiki.kr/w/자료 구조"},{"title":"선형_자료_구조","url":"https://itwiki.kr/w/선형_자료_구조"},{"title":"비선형 자료 구조","url":"https://itwiki.kr/w/비선형 자료 구조"}],"explain":{"ai":["<p>자료구조의 종류에는 선형구조와 비선형구조가 있다. 선형구조는 자료가 순차적으로 나열된 구조이며, 비선형구조는 자료가 특별한 순서 없이 연결된 구조이다. 데이터를 삽입하거나 삭제할 때 마지막에 삽입된 데이터가 먼저 삭제되는 선입선출 구조로 구현된 자료구조가 큐이다. 큐는 선형구조에 해당한다. </p>\n<p>스택은 후입선출구조로 구현된 자료구조로, 후입선출 구조란 마지막에 삽입된 데이터가 먼저 삭제되는 구조이다. 스택은 서브루틴 호출, 인터럽트 처리, 수식 계산 및 수식 표기법 등에 응용된다. </p>\n<p>따라서 자료구조에 대한 설명으로 틀린 것은 1번. 즉 큐는 비선형구조에 해당한다는 설명이다.</p>"]}},{"id":"13709","number":31,"category":"소프트웨어 개발","type":"choice","subject":"다음 중 블랙박스 검사 기법은?","choices":[{"n":1,"html":"경계값 분석"},{"n":2,"html":"조건 검사"},{"n":3,"html":"기초 경로 검사"},{"n":4,"html":"루프 검사"}],"answer":[1],"wiki":[{"title":"블랙박스 테스트","url":"https://itwiki.kr/w/블랙박스 테스트"}],"explain":{"ai":["<p>블랙박스 검사 기법은 소프트웨어의 내부 구조나 구현 방법에 관한 지식을 필요로 하지 않는다. 입력과 출력에만 집중하여 소프트웨어의 기능적 요구 사항을 충족하는지 검증한다. </p>\n<p>경계값 분석은 입력 데이터의 경계 값에 집중하여 오류가 발생할 가능성이 높은 지점을 식별하고 테스트하는 기법으로 블랙박스 검사 기법에 해당한다. </p>\n<p>조건 검사, 기초 경로 검사, 루프 검사는 화이트박스 검사 기법에 해당한다. 화이트박스 검사 기법은 소프트웨어의 내부 구조와 구현 방법을 검토하여 코드의 모든 경로가 적어도 한 번은 실행되도록 테스트한다. </p>\n<p>따라서 블랙박스 검사 기법은 1번 경계값 분석이 정답이다.</p>"]}},{"id":"13710","number":32,"category":"소프트웨어 개발","type":"choice","subject":"이진 검색 알고리즘에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"탐색 효율이 좋고 탐색 시간이 적게 소요된다."},{"n":2,"html":"검색할 데이터가 정렬되어 있어야 한다."},{"n":3,"html":"피보나치 수열에 따라 다음에 비교할 대상을 선정하여 검색한다."},{"n":4,"html":"비교횟수를 거듭할 때마다 검색 대상이 되는 데이터의 수가 절반으로 줄어든다."}],"answer":[3],"wiki":[{"title":"이진 검색","url":"https://itwiki.kr/w/이진 검색"}],"explain":{"ai":["<p>이진 검색 알고리즘은 데이터가 이미 정렬되어 있는 배열에서 특정 키 값을 갖는 요소를 검색하는 좋은 방법이다. 이진 검색은 배열의 중간에 있는 요소와 검색할 키 값을 비교하여 어느 쪽 배열의 반이 더 적절한지 판단하고 검색의 범위를 줄여나간다. </p>\n<p>이진 검색 알고리즘의 특징은 탐색 효율이 좋고 비교횟수를 거듭할 때마다 검색 대상이 되는 데이터의 수가 절반으로 줄어든다는 것이다. 이진 검색은 검색을 수행하기 전에 데이터가 정렬되어 있어야 하며, 이진 검색은 피보나치 수열과는 관련이 없다. </p>\n<p>따라서 피보나치 수열에 따라 다음에 비교할 대상을 선정하여 검색한다는 설명은 이진 검색 알고리즘에 대한 설명으로 틀린 것이다.</p>"]}},{"id":"13711","number":33,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어 품질목표 중 쉽게 배우고 사용할 수 있는 정도를 나타내는 것은?","choices":[{"n":1,"html":"Correctness"},{"n":2,"html":"Reliability"},{"n":3,"html":"Usability"},{"n":4,"html":"Integrity"}],"answer":[3],"explain":{"ai":["<p>소프트웨어 품질목표 중 쉽게 배우고 사용할 수 있는 정도를 나타내는 것은 사용성이라고 할 수 있다. 사용성은 사용자가 소프트웨어를 얼마나 쉽게 사용하고 이해할 수 있는지에 초점을 둔다. 사용성의 목표는 사용자 인터페이스를 직관적이고 쉽게 사용할 수 있도록 설계하여 사용자 오류를 최소화하는 것이다. 따라서 사용성이 높은 소프트웨어는 사용자에게 더 친숙하고 편리한 경험을 제공한다. 이러한 설명에基づいて 보았을 때, 사용성은 소프트웨어 개발에서 중요한 품질목표 중 하나이다.(enabled) \n위에서 설명한 사용성은 3번 정답인 Usability와 일치한다.</p>"]}},{"id":"13712","number":34,"category":"소프트웨어 개발","type":"choice","subject":"테스트 케이스에 일반적으로 포함되는 항목이 아닌 것은?","choices":[{"n":1,"html":"테스트 조건"},{"n":2,"html":"테스트 데이터"},{"n":3,"html":"테스트 비용"},{"n":4,"html":"예상 결과"}],"answer":[3],"explain":{"ai":["<p>테스트 케이스에는 일반적으로 테스트 조건, 테스트 데이터, 예상 결과 등이 포함된다. 테스트 조건은 테스트를 수행하는 이유와 목적을 정의하며, 테스트 데이터는 테스트를 수행하는 데 필요한 입력과 기대 출력을 말한다. 예상 결과는 테스트를 수행했을 때 기대되는 결과를 정의한다.</p>\n<p>그러나 테스트 비용은 일반적으로 테스트 케이스의 구성 요소가 아니다. 테스트 비용은 테스트를 плани하고 수행하는 데 필요한 리소스와 시간을 계산하는 것인데, 이 정보는 프로젝트 관리 또는 테스트 계획에 더 관련이 있다. 테스트 케이스는 테스트를 수행하고 결과를 검증하는 데 중점을 두기 때문이다. 따라서 테스트 비용은 테스트 케이스에 일반적으로 포함되는 항목이 아니다.</p>"]}},{"id":"13713","number":35,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어 설치 매뉴얼에 포함될 항목이 아닌 것은?","choices":[{"n":1,"html":"제품 소프트웨어 개요"},{"n":2,"html":"설치 관련 파일"},{"n":3,"html":"프로그램 삭제"},{"n":4,"html":"소프트웨어 개발 기간"}],"answer":[4],"explain":{"ai":["<p>소프트웨어 설치 매뉴얼은 사용자가 소프트웨어를 설치하고 실행하는 데 도움을 주는 문서입니다. 제품 소프트웨어 개요, 설치 관련 파일, 프로그램 삭제와 같은 내용은 설치와 관련이 있습니다. 하지만 소프트웨어 개발 기간은 설치와 직접적으로 관련이 없는 정보입니다. 설치 매뉴얼에서 사용자는 소프트웨어 설치를 위한 정보를 찾으므로 개발 기간과 같은 정보는 별로 중요하지 않습니다. 따라서 소프트웨어 개발 기간은 설치 매뉴얼에 포함될 항목이 아닙니다.</p>"]}},{"id":"13714","number":36,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어 형상관리(Configyration management)에 관한 설명으로 틀린 것은?","choices":[{"n":1,"html":"소프트웨어에서 일어나는 수정이나 변경을 알아내고 제어하는 것을 의미한다."},{"n":2,"html":"소프트웨어 개발의 전체 비용을 줄이고, 개발 과정의 여러 방해 요인이 최소화되도록 보증하는 것을 목적으로 한다."},{"n":3,"html":"형상관리를 위하여 구성된 팀을 “chief programmer team”이라고 한다."},{"n":4,"html":"형상관리의 기능 중 하나는 버전 제어 기술이다."}],"answer":[3],"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"},{"title":"버전 관리 시스템","url":"https://itwiki.kr/w/버전 관리 시스템"}],"explain":{"ai":["<p>소프트nockWARE 형상관리란 소프트웨어의 변경이나 수정을 관리하고 제어하는 것을 말한다. 소프트웨어 개발 과정에서 모든 변경이-version 효율적으로 관리되도록 해주며, 변경의 이력을 기록하고 추적할 수 있다. \n형상관리의 목적은 소프트웨어 개발의 전체 비용을 줄이고 개발 과정의 여러 방해 요인이 최소화되도록 보증하는 것이다. 또한 버전 제어 기술은 형상관리의 기본적인 기능 중 하나이다. \n그러나 형상관리를 위하여 구성된 팀을 chief programmer team이라고 하는 것은 맞지 않다. 형상관리팀은 소프트웨어형상관리의 담당팀이다. \nchief programmer team은 다른 개념이다.</p>"]}},{"id":"13715","number":37,"category":"소프트웨어 개발","type":"choice","subject":"퀵 정렬에 관한 설명으로 옳은 것은?","choices":[{"n":1,"html":"레코드의 키 값을 분석하여 같은 값끼리 그 순서에 맞는 버킷에 분배하였다가 버킷의 순서대로 레코드를 꺼내어 정렬한다."},{"n":2,"html":"주어진 파일에서 인접한 두 개의 레코드 키 값을 비교하여 그 크기에 따라 레코드 위치를 서로 교환한다."},{"n":3,"html":"레코드의 많은 자료 이동을 없애고 하나의 파일을 부분적으로 나누어 가면서 정렬한다."},{"n":4,"html":"임의의 레코드 키와 매개변수(h)값만큼 떨어진 곳의 레코드 키를 비교하여 서로 교환해 가면서 정렬한다."}],"answer":[3],"wiki":[{"title":"퀵 정렬","url":"https://itwiki.kr/w/퀵 정렬"}],"explain":{"ai":["<p>퀵 정렬은 하나의 파일을 부분적으로 나누어 가면서 정렬하는 방법입니다. 이 방법은 레코드의 많은 자료 이동을 없애주기 때문에 효율적인 정렬 알고리즘으로 여겨집니다. 퀵 정렬은 피벗이라는 기준점을 선택하여 기준점보다 작은 값을 왼쪽에 그리고 큰 값을 오른쪽에 배치하는 방식으로 진행됩니다.这样하면 각 부분은 부분적으로 정렬된 상태가 되며, 이 과정을 반복하여 전체 레코드가 정렬되게 됩니다.</p>"]}},{"id":"13716","number":38,"category":"소프트웨어 개발","type":"choice","subject":"해싱 함수(Hashing Function)의 종류가 아닌 것은?","choices":[{"n":1,"html":"제곱법(mid-square)"},{"n":2,"html":"숫자분석법(digit analysis)"},{"n":3,"html":"개방주소법(open addressing)"},{"n":4,"html":"제산법(division)"}],"answer":[3],"wiki":[{"title":"해시","url":"https://itwiki.kr/w/해시"}],"explain":{"ai":["<p>해싱 함수는 데이터를 효율적으로 저장하고 검색할 수 있게 하는 함수로, 여러 종류가 있다. \n해싱 함수의 종류 중에 제곱법은 숫자를 제곱한 후 중간 부분을 추출하는 방식이고, \n숫자분석법은 키 값에 포함된 숫자들의 특징을分析하여 해시 값을 생성하는 방식이다. \n제산법은 키 값을 일정한 값으로 나눈 후 나머지를 해시 값으로 사용하는 방식이다. \n반면에 개방주소법은 충돌이 발생했을 때 다른 위치에 저장할 주소를 찾아가는 방식으로, \n해싱 함수의 종류가 아니다. \n따라서 해싱 함수의 종류가 아닌 것은 개방주소법이다.</p>"]}},{"id":"13717","number":39,"category":"소프트웨어 개발","type":"choice","subject":"필드 테스팅(field testing)이라고도 불리며 개발자 없이 고객의 사용 환경에 소프트웨어를 설치하여 검사를 수행하는 인수검사 기법은?","choices":[{"n":1,"html":"베타 검사"},{"n":2,"html":"알파 검사"},{"n":3,"html":"형상 검사"},{"n":4,"html":"복구 검사"}],"answer":[1],"wiki":[{"title":"인수 테스트","url":"https://itwiki.kr/w/인수 테스트"}],"explain":{"ai":["<p>베타 검사는 소프트웨어를 실제 사용자 환경에 배포하여 개발자의 직접적인 관리 없이 사용자 피드백을 수집하는 과정을 의미합니다. 이 방법은 필드 테스팅이라고도 불리며, 실제 사용 상황에서의 소프트웨어 성능과 사용자 경험을 평가하는데 중점을 둡니다. 따라서, 고객의 실제 환경에서 개발자 없이 직접 테스트를 진행하는 인수검사 기법은 1번, 베타 검사입니다. 알파 검사는 주로 개발자 환경 내에서 이루어지고, 형상 검사와 복구 검사는 각각 소프트웨어의 일관성과 오류 복구 능력을 중점으로 하는 다른 유형의 테스트입니다.</p>"]}},{"id":"13718","number":40,"category":"소프트웨어 개발","type":"choice","subject":"다음 트리를 Preorder 운행법으로 운행할 경우 다섯 번째로 탐색되는 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"C"},{"n":2,"html":"E"},{"n":3,"html":"G"},{"n":4,"html":"H"}],"answer":[2]},{"id":"13719","number":41,"category":"데이터베이스 구축","type":"choice","subject":"결과 값이 아래와 같을 때 SQL 질의로 옳은 것은?","extra":"<pre class=\"contents\"><table>\r\n\r\n  <tr>\r\n    <th colspan=\"3\">[공급자] Table</th>\r\n  </tr>\r\n\r\n\r\n  <tr>\r\n    <td>공급자번호</td>\r\n    <td>공급자명</td>\r\n    <td>위치</td>\r\n  </tr>\r\n  <tr>\r\n    <td>16</td>\r\n    <td>대신공업사</td>\r\n    <td>수원</td>\r\n  </tr>\r\n  <tr>\r\n    <td>27</td>\r\n    <td>삼진사</td>\r\n    <td>서울</td>\r\n  </tr>\r\n  <tr>\r\n    <td>39</td>\r\n    <td>삼양사</td>\r\n    <td>인천</td>\r\n  </tr>\r\n  <tr>\r\n    <td>62</td>\r\n    <td>진아공업사</td>\r\n    <td>대전</td>\r\n  </tr>\r\n  <tr>\r\n    <td>70</td>\r\n    <td>신촌상사</td>\r\n    <td>서울</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"3\">[결과]</td>\r\n  </tr>\r\n  <tr>\r\n    <td>공급자번호</td>\r\n    <td>공급자명</td>\r\n    <td>위치</td>\r\n  </tr>\r\n  <tr>\r\n    <td>16</td>\r\n    <td>대신공업사</td>\r\n    <td>수원</td>\r\n  </tr>\r\n  <tr>\r\n    <td>70</td>\r\n    <td>신촌상사</td>\r\n    <td>서울</td>\r\n  </tr>\r\n\r\n</table></pre>","choices":[{"n":1,"html":"SELECT * FROM 공급자 WHERE공급자명 LIKE '%신%';"},{"n":2,"html":"SELECT * FROM 공급자 WHERE공급자명 LIKE '%대%';"},{"n":3,"html":"SELECT * FROM 공급자 WHERE공급자명 LIKE '%사%';"},{"n":4,"html":"SELECT * FROM 공급자 WHERE공급자명 IS NOT NULL;"}],"answer":[1],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>정답은 1번입니다. 문제에서 제시된 결과 테이블에는 '대신공업사'와 '신촌상사'가 포함되어 있습니다. 하지만 결과에만 존재하는 공급자는 '대신공업사'로, 이 공급자명은 '신'자를 포함하고 있습니다. </p>\n<p>1번 보기 <code>SELECT * FROM 공급자 WHERE 공급자명 LIKE '%신%';</code> 는 '신'이라는 글자를 포함하는 모든 공급자를 선택하므로, 결과에 정확히 해당하는 '대신공업사'를 포함합니다.</p>\n<p>다른 보기들을 살펴보면:</p>\n<ul>\n<li>2번 <code>LIKE '%대%'</code>는 '대'를 포함하는 모든 공급자를 선택하므로, '대신공업사' 외에도 다른 공급자도 포함될 가능성이 있습니다.</li>\n<li>3번 <code>LIKE '%사%'</code>는 '사'를 포함하는 모든 공급자를 선택하므로, 결과에 있는 두 공급자 모두 포함되지만 조건이 너무 넓습니다.</li>\n<li>4번 <code>IS NOT NULL</code>은 NULL이 아닌 모든 레코드를 선택하므로, 테이블의 모든 레코드를 반환하게 됩니다.</li>\n</ul>\n<p>따라서, 주어진 결과에 정확히 부합하는 조건은 1번 보기입니다.</p>"]}},{"id":"13720","number":42,"category":"데이터베이스 구축","type":"choice","subject":"다음에서 설명하는 스키마(Schema)는?","extra":"<pre class=\"contents\">데이터베이스 전체를 정의한 것으로 데이터 개체, 관계, 제약조건, 접근권한, 무결성 규칙 등을 명세한 것</pre>","choices":[{"n":1,"html":"개념 스키마"},{"n":2,"html":"내부 스키마"},{"n":3,"html":"외부 스키마"},{"n":4,"html":"내용 스키마"}],"answer":[1],"wiki":[{"title":"스키마","url":"https://itwiki.kr/w/스키마"}],"explain":{"ai":["<p>데이터베이스의 스키마는 데이터베이스의 구조와 제약조건을 정의한 것이다. 스키마는 데이터베이스의 전체적인 구조를 정의하며, 데이터 개체, 관계, 제약조건, 접근권한, 무결성 규칙 등을 포함한다. </p>\n<p>이 중에서 개념 스키마는 데이터베이스의 전체적인 구조를 논리적으로 정의한 것으로, 데이터 개체, 속성, 관계 등을 정의한다. 이는 데이터베이스를 설계하고 구축하는 데 중요한 역할을 한다. </p>\n<p>내부 스키마는 데이터베이스의 물리적인 저장 구조를 정의하며, 외부 스키마는 사용자들이 데이터베이스를 어떻게 볼 수 있는지를 정의한다. 내용 스키마는 실제로 저장되는 데이터의 구조를 정의한다. </p>\n<p>Sniper/／IRROR(pointer ไมौज$options에 따르면資料 전체를 정의한 것으로 데이터 개체, 관계, 제약조건, 접근권한, 무결성 규칙 등을 명세한 것이 개념 스키마에 해당된다. 따라서 정답은 1번이다.</p>"]}},{"id":"13721","number":43,"category":"데이터베이스 구축","type":"choice","subject":"데이터베이스 설계 단계 중 저장 레코드 양식설계, 레코드 집중의 분석 및 설계, 접근 경로 설계와 관계되는 것은?","choices":[{"n":1,"html":"논리적 설계"},{"n":2,"html":"요구 조건 분석"},{"n":3,"html":"개념적 설계"},{"n":4,"html":"물리적 설계"}],"answer":[4],"explain":{"ai":["<p>데이터베이스 설계는 개념적 설계, 논리적 설계, 물리적 설계의 3단계로 나뉜다. 물리적 설계 단계에서는 저장 레코드 양식설계, 레코드 집중의 분석 및 설계, 접근 경로 설계 등이 수행된다. 저장 레코드 양식설계는 데이터를 실제로 저장할 때의 양식을 결정하는 것으로, 데이터가 어떻게 저장되고 유지되는지에 관한 내용이다. 레코드 집중의 분석 및 설계는 데이터베이스의 성능을 향상시키기 위해 데이터를 어떻게 저장하고 관리할지 결정하는 단계이다. 접근 경로 설계는 데이터에 접근하는 경로를 설계하는 단계로, 데이터베이스의 성능과 보안을 결정하는重要한 단계이다. 이러한 모든 단계는 물리적 설계에 해당하므로 정답은 물리적 설계이다.</p>"]}},{"id":"13722","number":44,"category":"데이터베이스 구축","type":"choice","subject":"다음 릴레이션의 카디널리티와 차수가 옳게 나타낸 것은?","extra":"<pre class=\"contents\"><table>\r\n\r\n  <tr>\r\n    <th>아이디</th>\r\n    <th>성명</th>\r\n    <th>나이</th>\r\n    <th>등급</th>\r\n    <th>적립금</th>\r\n    <th>가입연도</th>\r\n  </tr>\r\n\r\n\r\n  <tr>\r\n    <td>yuyu01</td>\r\n    <td>원유철</td>\r\n    <td>36</td>\r\n    <td>3</td>\r\n    <td>2000</td>\r\n    <td>2008</td>\r\n  </tr>\r\n  <tr>\r\n    <td>sykim10</td>\r\n    <td>김성일</td>\r\n    <td>29</td>\r\n    <td>2</td>\r\n    <td>3300</td>\r\n    <td>2014</td>\r\n  </tr>\r\n  <tr>\r\n    <td>kshan4</td>\r\n    <td>한경선</td>\r\n    <td>45</td>\r\n    <td>3</td>\r\n    <td>2800</td>\r\n    <td>2009</td>\r\n  </tr>\r\n  <tr>\r\n    <td>namsu52</td>\r\n    <td>이남수</td>\r\n    <td>33</td>\r\n    <td>5</td>\r\n    <td>1000</td>\r\n    <td>2016</td>\r\n  </tr>\r\n\r\n</table></pre>","choices":[{"n":1,"html":"카디널리티 : 4, 차수 : 4"},{"n":2,"html":"카디널리티 : 4, 차수 : 6"},{"n":3,"html":"카디널리티 : 6, 차수 : 4"},{"n":4,"html":"카디널리티 : 6, 차수 : 6"}],"answer":[2],"explain":{"ai":["<p>릴레이션의 <strong>카디널리티</strong>는 행의 수를 의미하며, 주어진 예제에서는 총 4개의 데이터 행이 존재하므로 카디널리티는 4가 되어야 합니다. 하지만 정답은 2번으로 지정되어 있으므로 이 부분에 오류가 있는 것처럼 보이지만, 문제의 정답에 따른 해석에 따르면 다른 요소를 고려해야 할 수도 있습니다.</p>\n<p>반면, <strong>차수</strong>는 열의 수를 나타냅니다. 주어진 릴레이션에는 <code>아이디</code>, <code>성명</code>, <code>나이</code>, <code>등급</code>, <code>적립금</code>, <code>가입연도</code> 총 6개의 열이 있습니다. 따라서 차수는 6입니다.</p>\n<p>따라서 문제의 정답이 2번으로 지정된 것에 따라, 해설은 다음과 같습니다:</p>\n<ul>\n<li><strong>정답 해설</strong>: 주어진 옵션 중에서 차수가 정확히 6인 것은 2번입니다. 문제의 의도를 정확히 파악하기 위해서는 카디널리티에 대한 정답이 예상과 다를 수 있으나, 주어진 선택지에 따라 <strong>카디널리티는 4 (주어진 데이터에 따른 정확한 값)</strong>, <strong>차수는 6</strong>이 올바른 설명입니다. 정답으로 제시된 2번이 차수에 대해 맞는 표현을 하고 있기에 선택되었습니다. 하지만 카디널리티 부분은 주어진 데이터와 일치하지 않는 점에 주의가 필요합니다.</li>\n</ul>"]}},{"id":"13723","number":45,"category":"데이터베이스 구축","type":"choice","subject":"다음과 같은 트랙잭션의 특성은?","extra":"<pre class=\"contents\">시스템이 가지고 있는 고정요소는 트랜잭션 수행 전과 트랜잭션 수행 완료 후의 상태가 같아야 한다.</pre>","choices":[{"n":1,"html":"원자성(atomicity)"},{"n":2,"html":"일관성(consistency)"},{"n":3,"html":"격리성(isolation)"},{"n":4,"html":"영속성(durability)"}],"answer":[2],"wiki":[{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"},{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"explain":{"ai":["<p>트랜잭션의 특성 중에서 시스템이 가지고 있는 고정요소는 트랜잭션 수행 전과 트랜잭션 수행 완료 후의 상태가 같아야 한다는 것은 일관성을 의미한다. 트랜잭션이 수행되기 전의 데이터베이스 상태와 수행 후의 데이터베이스 상태가 일관성이 유지되어야 하기 때문이다. 원자성은 트랜잭션의 수행이 완료되지 않았을 경우에는 Rolled Back되어야 한다는 특성을 의미하고, 격리성은 여러 트랜잭션이同時에 수행될 때 각각의 트랜잭션이孤立된 것처럼 수행되어야 한다는 특성을 의미하며, 영속성은 트랜잭션이 완료되면 그 결과가 데이터베이스에 영구히 반영되어야 한다는 특성을 의미한다. 따라서 시스템이 가지고 있는 고정요소는 트랜잭션 수행 전과 트랜잭션 수행 완료 후의 상태가 같아야 한다라는 것은 일관성을 의미하기 때문에 정답은 일관성이다.</p>"]}},{"id":"13724","number":46,"category":"데이터베이스 구축","type":"choice","subject":"병행제어의 로킹(Locking) 단위에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"데이터베이스, 파일, 레코드 등은 로킹 단위가 될 수 있다."},{"n":2,"html":"로킹 단위가 작아지면 로킹 오버헤드가 증가한다."},{"n":3,"html":"한꺼번에 로킹할 수 있는 단위를 로킹단위라고 한다."},{"n":4,"html":"로킹 단위가 작아지면 병행성 수준이 낮아진다."}],"answer":[4],"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"explain":{"ai":["<p>로킹 단위는 트랜잭션이 데이터베이스에 접근할 수 있는 단위를 말한다. 로킹 단위는 데이터베이스, 파일, 레코드 등이 될 수 있다. 로킹 단위가 작아지면 로킹 오버헤드가 증가한다. 로킹 오버헤드는 로킹 단위를 설정하고 해제하는 비용을 말한다. 로킹 단위가 작아지면 트랜잭션이 데이터에 접근하기 위해 더 많은 로킹 단위를 설정하고 해제해야 하므로 오버헤드가 증가한다. 로킹 단위가 작아지면 병행성 수준이提高된다. 병행성 수준은 여러 트랜잭션이 동시에 실행될 수 있는 수준을 말한다. 로킹 단위가 작아지면 더 많은 트랜잭션이 동시에 실행될 수 있으므로 병행성 수준이 높아진다. 따라서 로킹 단위가 작아지면 병행성 수준이 낮아진다는 설명은 옳지 않다.</p>"]}},{"id":"13725","number":47,"category":"데이터베이스 구축","type":"choice","subject":"뷰(VIEW)에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"DBA는 보안 측면에서 뷰를 활용할 수 있다."},{"n":2,"html":"뷰 위에 또 다른 뷰를 정의할 수 있다."},{"n":3,"html":"뷰에 대한 삽입, 갱신, 삭제 연산 시 제약사항이 따르지 않는다."},{"n":4,"html":"독립적인 인덱스를 가질 수 없다."}],"answer":[3],"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"explain":{"ai":["<p>뷰는 가상 테이블로 실제 데이터를 저장하지 않는다. 뷰를 사용하면 복잡한 쿼리를 간단하게 만들 수 있고 데이터 보안도 강화할 수 있다. \nDBA는 보안 측면에서 뷰를 활용할 수 있다. 예를 들어 중요한 데이터만 노출시키고 기본 테이블의 전체 데이터를 숨길 수 있다. \n또한 뷰 위에 또 다른 뷰를 정의할 수 있다. \n뷰에는 독립적인 인덱스를 가질 수 없다. \n그러나 뷰에 대한 삽입, 갱신, 삭제 연산 시 제약사항이 따른다. 즉, 뷰를 통해 데이터를 수정하려면 뷰의 정의와 기본 테이블의 구조에 따라야 하며 일부 연산은 제한될 수 있다. \n따라서 뷰에 대한 삽입, 갱신, 삭제 연산 시 제약사항이 따르지 않는다는 설명은 옳지 않다.</p>"]}},{"id":"13726","number":48,"category":"데이터베이스 구축","type":"choice","subject":"다음 정의에서 말하는 기본 정규형은?","extra":"<pre class=\"contents\">어떤 릴레이션 R에 속한 모든 도메인이 원자값(Atomic Value)만으로 되어 있다.</pre>","choices":[{"n":1,"html":"제1정규형(1NF)"},{"n":2,"html":"제2정규형(2NF)"},{"n":3,"html":"제3정규형(3NF)"},{"n":4,"html":"보이스/코드 정규형(BCNF)"}],"answer":[1],"explain":{"ai":["<p>정답은 제1정규형으로 릴레이션의 모든 속성 값이 원자값으로 구성되어야 한다. 이는 속성 값이 더 이상 분해될 수 없음을 의미한다. 즉, 하나의 속성에 여러 개의 값을 가질 수 없다는 것을 말한다. 제1정규형은 릴레이션의 기본적인 구조를 제공하는 데 중요하다. 다른 정규형은 제1정규형을 기반으로하며, 각 정규형은 데이터의 중복과 종속성을 줄이는 데 도움을 준다. 제1정규형은 데이터베이스 설계의 기본 단계로, 이후 다른 정규형으로 진행한다.</p>"]}},{"id":"13727","number":49,"category":"데이터베이스 구축","type":"choice","subject":"릴레이션 R1에 속한 애튜리뷰트의 조합인 외래키를 변경하려면 이를 참조하고 있는 릴레이션 R2의 기본키도 변경해야 하는데 이를 무엇이라 하는가?","choices":[{"n":1,"html":"정보 무결성"},{"n":2,"html":"고유 무결성"},{"n":3,"html":"널 제약성"},{"n":4,"html":"참조 무결성"}],"answer":[4],"wiki":[{"title":"무결성","url":"https://itwiki.kr/w/무결성"},{"title":"참조 무결성","url":"https://itwiki.kr/w/참조 무결성"}],"explain":{"ai":["<p>릴레이션 R1에 속한 애트리뷰트의 조합인 외래키를 변경하려면 이를 참조하고 있는 릴레이션 R2의 기본키도 변경해야 하는데 이를 참조 무결성이라 한다. 참조 무결성은 릴레이션 간의 일관성을 유지하는 것으로 외래키 제약을 통해 릴레이션 간의 참조 관계가 올바르게 유지되도록 하는 것을 말한다.즉, 릴레이션 R1의 외래키와 릴レイ션 R2의 기본키와 일관성을 유지하는 것 이다.</p>"]}},{"id":"13728","number":50,"category":"데이터베이스 구축","type":"choice","subject":"시스템 카탈로그에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"시스템 카탈로그의 갱신은 무결성 유지를 위하여 SQL을 이용하여 사용자가 직접 갱신하여야 한다."},{"n":2,"html":"데이터베이스에 포함되는 데이터 객체에 대한 정의나 명세에 대한 정보를 유지관리한다."},{"n":3,"html":"DBMS가 스스로 생성하고 유지하는 데이터베이스 내의 특별한 테이블의 집합체이다."},{"n":4,"html":"카탈로그에 저장된 정보를 메타 데이터라고도 한다."}],"answer":[1],"wiki":[{"title":"시스템 카탈로그","url":"https://itwiki.kr/w/시스템 카탈로그"}],"explain":{"ai":["<p>시스템 카탈로그는 DBMS가 스스로 생성하고 유지하는 데이터베이스 내의 특별한 테이블의 집합체이다. 시스템 카탈로그는 데이터베이스에 포함되는 데이터 객체에 대한 정의나 명세에 대한 정보를 유지관리하며카탈로그에 저장된 정보를 메타 데이터라고도 한다. 시스템 카탈로그의 갱신은 무결성 유지를 위하여 사용자가 직접하지 않으며 DBMS가 자동으로 갱신한다. 즉 시스템 카탈로그의 갱신이 사용자에의해 SQL을 이용하여 직접 갱신해야 한다는 말은 틀리다.</p>"]}},{"id":"13729","number":51,"category":"데이터베이스 구축","type":"choice","subject":"조건을 만족하는 릴레이션의 수평적 부분집합으로 구성하며, 연산자의 기호는 그리스 문자 시그마(σ)를 사용하는 관계대수 연산은?","choices":[{"n":1,"html":"Select"},{"n":2,"html":"Project"},{"n":3,"html":"Join"},{"n":4,"html":"Division"}],"answer":[1],"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"explain":{"ai":["<p>해당 문제는 관계대수 연산 중 선택 연산을 묻는 문제입니다. 선택 연산은 주어진 조건을 만족하는 튜플을 릴레이션에서 추출하여 새로운 릴레이션을 만드는 연산입니다. 이 연산은 릴레이션의 행을 필터링하는 효과를 가지며, 관계대수에서 시그마 기호를 사용하여 나타냅니다. 따라서 선택 연산은 릴레이션의 수평적 부분집합을 구성하며, 이를 나타내는 연산자 기호가 그리스 문자 시그마입니다. </p>\n<p>선택 연산은 릴레이션에서 특정 속성 값을 기준으로 행을 선택하여 새로운 릴레이션을 생성합니다. 예를 들어 특정 이름을 가진 고객을 찾는 경우와 같이 조건을 만족하는 튜플만을 추출하여 새로운 릴레이션을 만듭니다. 이러한 이유로 선택 연산은 릴레이션의 수평적 부분집합으로 구성되며, 연산자의 기호로 그리스 문자 시그마가 사용됩니다.</p>"]}},{"id":"13730","number":52,"category":"데이터베이스 구축","type":"choice","subject":"SQL에서 스키마(schema), 도메인(domain), 테이블(table), 뷰(view), 인덱스(index)를 정의하거나 변경 또는 삭제할 때 사용하는 언어는?","choices":[{"n":1,"html":"DML(Data Manipulation Language)"},{"n":2,"html":"DDL(Data Definition Language)"},{"n":3,"html":"DCL(Data Control Language)"},{"n":4,"html":"IDL(Interactive Data Language)"}],"answer":[2],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>데이터베이스의 구조를 정의하거나 변경할 때 사용하는 언어를 데이터 정의 언어라고 한다. 스키마나 도메인, 테이블, 뷰, 인덱스를 생성하거나 변경, 삭제하는 작업은 데이터베이스의 구조나 레이아웃과 관련된 작업이기 때문에 데이터 정의 언어를 사용한다. 따라서 데이터베이스의 구조를 정의하거나 변경할 때 사용하는 언어는 DDL이다.</p>"]}},{"id":"13731","number":53,"category":"데이터베이스 구축","type":"choice","subject":"정규화를 거치지 않아 발생하게 되는 이상(anomaly) 현상의 종류에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"삭제 이상이란 릴레이션에서 한 튜플을 삭제할 때 의도와는 상관없는 값들로 함께 삭제되는 연쇄 삭제 현상이다."},{"n":2,"html":"삽입 이상이란 릴레이션에서 데이터를 삽입할 때 의도와는 상관없이 원하지 않는 값들로 함께 삽입되는 현상이다."},{"n":3,"html":"갱신 이상이란 릴레이션에서 튜플에 있는 속성값을 갱신할 때 일부 튜플의 정보만 갱신되어 정보에 모순이 생기는 현상이다."},{"n":4,"html":"종속 이상이란 하나의 릴레이션에 하나 이상의 함수적 종속성이 존재하는 현상이다."}],"answer":[4],"explain":{"ai":["<p>정규화를 거치지 않아 발생하는 이상 현상의 종류 중에서 옳지 않은 설명은 종속 이상에 대한 설명이다. 종속 이상은 하나의 릴레이션에 하나 이상의 함수적 종속성이 존재하는 현상을 의미하지 않는다. 함수적 종속성이란 한 속성이 다른 속성에 의해 결정되는 것을 말한다.</p>\n<p>정규화를 거치지 않아 발생하는 이상 현상의 종류는 삭제 이상, 삽입 이상, 갱신 이상이 있다. 삭제 이상은 릴레이션에서 한 튜플을 삭제할 때 의도하지 않은 값들로 함께 삭제되는 현상이다. 삽입 이상은 릴레이션에서 데이터를 삽입할 때 의도하지 않은 값들로 함께 삽입되는 현상이다. 갱신 이상은 릴레이션에서 튜플에 있는 속성값을 갱신할 때 일부 튜플의 정보만 갱신되어 정보에 모순이 생기는 현상이다.</p>"]}},{"id":"13732","number":54,"category":"데이터베이스 구축","type":"choice","subject":"관계 데이터 모델에서 릴레이션(relation)에 관한 설명으로 옳은 것은?","choices":[{"n":1,"html":"릴레이션의 각 행을 스키마(schema)라 하며, 예로 도서 릴레이션을 구성하는 스키마에서는 도서번호, 도서명, 저자, 가격 등이 있다."},{"n":2,"html":"릴레이션의 각 열을 튜플(tuple)이라 하며, 하나의 튜플은 각 속성에서 정의된 값을 이용하여 구성된다."},{"n":3,"html":"도메인(domain)은 하나의 속성이 가질 수 있는 같은 타입의 모든 값의 집합으로 각 속성의 도메인은 원자값을 갖는다."},{"n":4,"html":"속성(attribute)은 한 개의 릴레이션의 논리적인 구조를 정의한 것으로 릴레이션의 이름과 릴레이션에 포함된 속성들의 집합을 의미한다."}],"answer":[3],"explain":{"ai":["<p>정답은 <strong>3번</strong>입니다.</p>\n<ul>\n<li>\n<p><strong>1번은 틀렸습니다.</strong> 릴레이션의 각 행을 <strong>튜플(tuple)</strong>이라고 합니다. 스키마는 릴레이션의 구조, 즉 속성 이름과 데이터 타입을 정의하는 것입니다. 도서 릴레이션의 스키마는 \"도서번호(int), 도서명(varchar), 저자(varchar), 가격(float)\"와 같이 표현됩니다.</p>\n</li>\n<li>\n<p><strong>2번은 틀렸습니다.</strong> 릴레이션의 각 열을 <strong>속성(attribute)</strong>이라고 합니다. 튜플은 릴레이션의 한 행, 즉 특정 개체에 대한 정보를 담고 있는 집합입니다.</p>\n</li>\n<li>\n<p><strong>3번은 옳습니다.</strong> 도메인은 속성이 가질 수 있는 값의 범위를 나타냅니다.  '도서가격' 속성의 도메인은 모든 숫자 값, 특히 양수로 제한될 수 있습니다. 도메인이 원자값을 가져야 한다는 것은 각 속성 값이 더 이상 분해될 수 없는 기본적인 단위여야 함을 의미합니다. 예를 들어, '저자' 속성은 '김철수, 박영희' 와 같이 복합 값을 가질 수 없습니다.</p>\n</li>\n<li>\n<p><strong>4번은 틀렸습니다.</strong> 속성은 릴레이션의 각 열에 해당하는 하나의 데이터 항목을 나타냅니다. 릴레이션의 논리적 구조는 스키마로 정의됩니다. 즉, 릴레이션 이름과 속성 이름 및 데이터 타입의 집합이 릴레이션의 구조를 결정합니다.</p>\n</li>\n</ul>"]}},{"id":"13733","number":55,"category":"데이터베이스 구축","type":"choice","subject":"3NF에서 BCNF가 되기 위한 조건은?","choices":[{"n":1,"html":"이행적 함수 종속 제거"},{"n":2,"html":"부분적 함수 종속 제거"},{"n":3,"html":"다치 종속 제거"},{"n":4,"html":"결정자이면서 후보 키가 아닌 것 제거"}],"answer":[4],"explain":{"ai":["<p>3NF에서 BCNF로升 cấp하기 위해서는 결정자가 후보 키가 아닌 것을 제거해야 한다. \n즉, 후보키가 아닌 결정자는 모두 제거해야 한다. \n이 과정을 통해 関係형 데이터베이스의 무결성을 보장하고 데이터冗余를 줄일 수 있다. \n이러한 조건을 만족하면 3NF에서 BCNF로 승격될 수 있다. \n간단히 말해 후보 키가 아닌 결정자는 모두 제거해야 하며 正确答案은 4번이다.</p>"]}},{"id":"13734","number":56,"category":"데이터베이스 구축","type":"choice","subject":"데이터베이스 성능에 많은 영향을 주는 DBMS의 구성 요소로 테이블과 클러스터에 연관되어 독립적인 저장 공간을 보유하며, 데이터베이스에 저장된 자료를 더욱 빠르게 조회하기 위하여 사용되는 것은?","choices":[{"n":1,"html":"인덱스(Index)"},{"n":2,"html":"트랙잭션(Transaction)"},{"n":3,"html":"역정규화(Denormalization)"},{"n":4,"html":"트리거(Trigger)"}],"answer":[1],"explain":{"ai":["<p>데이터베이스 성능에 많은 영향을 주는 요소 중 하나는 데이터에 빠르게 접근할 수 있는 방법을 제공하는 구성 요소입니다. 테이블과 클러스터에 연관되어 독립적인 저장 공간을 보유하며 데이터베이스에 저장된 자료를 더욱 빠르게 조회하기 위하여 사용됩니다. </p>\n<p>이러한 요구 사항을 만족하는 구성 요소는 인덱스입니다. 인덱스는 데이터베이스의 검색 속도를 높여주는 자료 구조로, 데이터의 빠른 조회를 용이하게 합니다. 데이터베이스 시스템에서 인덱스는 키-값 쌍으로 구성되며, 데이터에 대한 빠른 접근을 제공하여 데이터베이스의 성능을 개선하는 데 중요한 역할을 합니다. </p>\n<p>따라서 데이터베이스 성능을 향상시키고 데이터를 더욱 빠르게 조회하기 위하여 사용되는 구성 요소는 인덱스입니다.</p>"]}},{"id":"13735","number":57,"category":"데이터베이스 구축","type":"choice","subject":"아래의 SQL문을 실행한 결과는?","extra":"<pre class=\"contents\"><table>\r\n\r\n  <tr>\r\n    <th colspan=\"8\">[R1 테이블]</th>\r\n  </tr>\r\n\r\n\r\n  <tr>\r\n    <td>학번</td>\r\n    <td colspan=\"2\">이름</td>\r\n    <td colspan=\"2\">학년</td>\r\n    <td colspan=\"2\">학과</td>\r\n    <td>주소</td>\r\n  </tr>\r\n  <tr>\r\n    <td>1000</td>\r\n    <td colspan=\"2\">홍길동</td>\r\n    <td colspan=\"2\">4</td>\r\n    <td colspan=\"2\">컴퓨터</td>\r\n    <td>서울</td>\r\n  </tr>\r\n  <tr>\r\n    <td>2000</td>\r\n    <td colspan=\"2\">김철수</td>\r\n    <td colspan=\"2\">3</td>\r\n    <td colspan=\"2\">전기</td>\r\n    <td>경기</td>\r\n  </tr>\r\n  <tr>\r\n    <td>3000</td>\r\n    <td colspan=\"2\">강남길</td>\r\n    <td colspan=\"2\">1</td>\r\n    <td colspan=\"2\">컴퓨터</td>\r\n    <td>경기</td>\r\n  </tr>\r\n  <tr>\r\n    <td>4000</td>\r\n    <td colspan=\"2\">오말자</td>\r\n    <td colspan=\"2\">4</td>\r\n    <td colspan=\"2\">컴퓨터</td>\r\n    <td>경기</td>\r\n  </tr>\r\n  <tr>\r\n    <td>5000</td>\r\n    <td colspan=\"2\">장미화</td>\r\n    <td colspan=\"2\">2</td>\r\n    <td colspan=\"2\">전자</td>\r\n    <td>서울</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"8\">[R2 테이블]</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">학번</td>\r\n    <td colspan=\"2\">과목번호</td>\r\n    <td colspan=\"2\">성적</td>\r\n    <td colspan=\"2\">점수</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">1000</td>\r\n    <td colspan=\"2\">C100.</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">91</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">1000</td>\r\n    <td colspan=\"2\">C200</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">94</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">2000</td>\r\n    <td colspan=\"2\">C300</td>\r\n    <td colspan=\"2\">B</td>\r\n    <td colspan=\"2\">85</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">3000</td>\r\n    <td colspan=\"2\">C400</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">90</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">3000</td>\r\n    <td colspan=\"2\">C500</td>\r\n    <td colspan=\"2\">C</td>\r\n    <td colspan=\"2\">75</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">3000</td>\r\n    <td colspan=\"2\">C100</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">90</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">4000</td>\r\n    <td colspan=\"2\">C400</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">95</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">4000</td>\r\n    <td colspan=\"2\">C500</td>\r\n    <td colspan=\"2\">A</td>\r\n    <td colspan=\"2\">91</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">4000</td>\r\n    <td colspan=\"2\">C100</td>\r\n    <td colspan=\"2\">B</td>\r\n    <td colspan=\"2\">80</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">4000</td>\r\n    <td colspan=\"2\">C200</td>\r\n    <td colspan=\"2\">C</td>\r\n    <td colspan=\"2\">74</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">5000</td>\r\n    <td colspan=\"2\">C400</td>\r\n    <td colspan=\"2\">B</td>\r\n    <td colspan=\"2\">85</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"8\">[SQL문]</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"8\">SELECT 이름FROM R1WHERE 학번 IN(SELECT 학번FROM R2WHERE 과목번호＝ ‘C100’);</td>\r\n  </tr>\r\n\r\n</table></pre>","choices":[{"n":1,"html":"이름: 홍길동, 강남길, 장미화"},{"n":2,"html":"이름: 홍길동, 강남길, 오말자"},{"n":3,"html":"이름: 홍길동, 김철수, 김남길, 오말자, 장미화"},{"n":4,"html":"이름: 홍길동, 김철수"}],"answer":[2],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>R1 테이블과 R2 테이블에서 학번이 일치하고 과목번호가 C100 인 학생들의 이름을 찾는 SQL 문이 실행됩니다. \nR2 테이블에서 과목번호가 C100 인 학번은 1000, 3000, 4000입니다. \n이러한 학번을 가진 학생들의 이름은 홍길동, 강남길, 오말자입니다. \n따라서 SQL 문을 실행한 결과는 이름: 홍길동, 강남길, 오말자입니다. \n因此 정답은 2번입니다.</p>"]}},{"id":"13736","number":58,"category":"데이터베이스 구축","type":"choice","subject":"『회원』테이블 생성 후 『주소』 필드(컬럼)가 누락되어 이를 추가하려고 한다. 이에 적합한 SQL명령어는?","choices":[{"n":1,"html":"DELETE"},{"n":2,"html":"RESTORE"},{"n":3,"html":"ALTER"},{"n":4,"html":"ACCESS"}],"answer":[3],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>회원 테이블에 주소 필드를 추가하려면 테이블의 구조를 수정해야 한다. 따라서 ALTER라는 SQL 명령어가 적합하다. ALTER는 테이블을 수정할 때 사용하는 명령어로, 테이블에 새로운 필드를 추가하거나 기존 필드를 삭제 또는 수정할 때 사용된다. </p>\n<p>다른 명령어들은 다음과 같은 용도로 사용된다. DELETE는 데이터를 삭제할 때, RESTORE는备份된 데이터베이스를 복구할 때, ACCESS는 데이터베이스에 접근할 때 사용한다. 따라서 이 경우에는 ALTER가 가장 적합한 명령어이다.</p>"]}},{"id":"13737","number":59,"category":"데이터베이스 구축","type":"choice","subject":"트랜잭션을 수행하는 도중 장애로 인해 손상된 데이터베이스를 손상되기 이전에 정상적인 상태로 복구시키는 작업은?","choices":[{"n":1,"html":"Recovery"},{"n":2,"html":"Commit"},{"n":3,"html":"Abort"},{"n":4,"html":"Restart"}],"answer":[1],"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"explain":{"ai":["<p>트랜잭션을 수행하는 도중 장애로 인해 데이터베이스가 손상되었을 때, 이를 이전의 정상적인 상태로 복구시키는 작업을.mean 이다. 데이터베이스 시스템은 장애가 발생했을 때 데이터의 일관성을 유지하기 위해 다양한 메커니즘을 사용하는데, 트랜잭션 복구 작업이 바로 그런 메커니즘 중 하나이다. </p>\n<p>이런 경우에 Recovery 작업을 통해 데이터베이스를 일관된 상태로 복구시킬 수 있다. Recovery 작업은 데이터베이스의 로그 파일을 분석하여 트랜잭션의 연산을 되돌리거나 재실행함으로써 데이터 일관성을 유지한다. </p>\n<p>Commit은 트랜잭션이 성공적으로 완료되었을 때 수행하는 작업이기 때문에, Abort는 트랜잭션을 중단시키는 작업이기 때문에, Restart는 시스템을 재시작하는 작업이기 때문에 이들로는 데이터베이스의 손상 복구를 위해서는 적절하지 않다. 따라서 데이터베이스의 정상적인 상태로 복구시키는 작업은 Recovery이다.</p>"]}},{"id":"13738","number":60,"category":"데이터베이스 구축","type":"choice","subject":"E-R 다이어그램의 표기법으로 옳지 않은 것은?","choices":[{"n":1,"html":"개체타입 - 사각형"},{"n":2,"html":"속성 - 타원"},{"n":3,"html":"관계집합 - 삼각형"},{"n":4,"html":"개체타입과 속성을 연결 – 선"}],"answer":[3],"wiki":[{"title":"ER 다이어그램","url":"https://itwiki.kr/w/ER 다이어그램"}],"explain":{"ai":["<p>E-R 다이어그램은 개체-관계 모델링에서 사용되는 도구로, 데이터베이스의 구조를 시각적으로 나타내는 데 사용된다. </p>\n<ul>\n<li>개체타입은 사각형으로 표시된다.</li>\n<li>속성은 타원으로 표시된다.</li>\n<li>관계집합은 마름모 또는 사각형으로 표시되며, 삼각형은 일반적으로 사용되지 않는다.</li>\n<li>개체타입과 속성은 선으로 연결된다.</li>\n</ul>\n<p>따라서 E-R 다이어그램의 표기법으로 옳지 않은 것은 관계집합을 표시하는 방법으로, 일반적으로 삼각형이 아닌 마름모나 사각형을 사용한다. 따라서 정답은 3번이다. 관계집합은 데이터베이스에서 중요한 개념으로, 엔티티 간의 관계를 표현하기 위해 사용되므로 정확한 표기법을 사용하는 것이 중요하다.</p>"]}},{"id":"13739","number":61,"category":"프로그래밍 언어 활용","type":"choice","subject":"다음 중 응집도가 가장 높은 것은?","choices":[{"n":1,"html":"절차적 응집도"},{"n":2,"html":"순차적 응집도"},{"n":3,"html":"우연적 응집도"},{"n":4,"html":"논리적 응집도"}],"answer":[2],"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"explain":{"ai":["<p>응집도는 모듈 내부 요소들이 서로関聯되어 있는 정도를 나타낸다. 여러 응집도 중에서 순차적 응집도는 모듈 내부의 요소들이 순차적으로 실행되어 하나의 기능을 수행할 때 나타나는 응집도이다. </p>\n<p>순차적 응집도는 모듈의 기능을 수행하는 데 필요한 요소들이 순차적으로 연결되어 있으므로 응집도가 가장 높다. 절차적 응집도는 모듈 내부의 요소들이 특정 절차에 따라 실행되지만, 순차적 응집도는 절차적 응집도보다 더 강한関聯성을 갖는다. </p>\n<p>우연적 응집도와 논리적 응집도는 모듈 내부의 요소들이 서로 간에 강한関聯성을 갖지 못하므로 응집도가 상대적으로 낮다. 따라서 순차적 응집도는 응집도가 가장 높은 응집도이다.</p>"]}},{"id":"13740","number":62,"category":"프로그래밍 언어 활용","type":"choice","subject":"OSI 7계층에서 물리적 연결을 이용해 신뢰성 있는 정보를 전송하려고 동기화, 오류제어, 흐름제어 등의 전송에러를 제어하는 계층은?","choices":[{"n":1,"html":"데이터 링크 계층"},{"n":2,"html":"물리 계층"},{"n":3,"html":"응용 계층"},{"n":4,"html":"표현 계층"}],"answer":[1],"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"explain":{"ai":["<p>OSI 7계층에서 물리적 연결을 이용해 신뢰성 있는 정보를 전송하려고 동기화, 오류제어, 흐름제어 등의 전송에러를 제어하는 계층은 데이터 링크 계층이야. \n이 계층은 열린 시스템들 간의 정보交換을 위한 接続의 설정, 유지, 종료 등에 필요한 기능을 제공하고, 프레임화, 주소 지정, 흐름 제어, 오류 감지 및 수정, 동기화 등 기능을 포함해. \n이 계층은 물리 계층과 네트워크 계층 사이의 중간 계층으로, 네트워크 위의 경로를 결정하고, 라우팅을 위한 주소 지정, 세그멘테이션 등 다양한 기능을 제공해. 데이터 전송의 신뢰성과 효율성을 높여주는 중요한 계층이라고 볼 수 있어.</p>"]}},{"id":"13741","number":63,"category":"프로그래밍 언어 활용","type":"choice","subject":"운영체제를 기능에 따라 분류할 경우 제어 프로그램이 아닌 것은?","choices":[{"n":1,"html":"데이터 관리 프로그램"},{"n":2,"html":"서비스 프로그램"},{"n":3,"html":"작업 제어 프로그램"},{"n":4,"html":"감시 프로그램"}],"answer":[2],"wiki":[{"title":"운영체제","url":"https://itwiki.kr/w/운영체제"}],"explain":{"ai":["<p>운영체제의 기능에 따라 분류할 경우 제어 프로그램은 컴퓨터 시스템의 자원과 작업을 관리하고 제어하는 프로그램이다. 작업 제어 프로그램, 감시 프로그램, 데이터 관리 프로그램은 모두 제어 프로그램에 해당한다. </p>\n<p>작업 제어 프로그램은 작업의 순서와 priority 등을 관리한다. 감시 프로그램은 시스템의 동작 상태를 감시하고 오류를 검출하며 처리하는 프로그램이다. 데이터 관리 프로그램은 데이터베이스와 파일 시스템을 관리하는 프로그램이다. </p>\n<p>그러나 서비스 프로그램은 사용자에게 다양한 서비스를 제공하는 프로그램으로서, 시스템의 자원 관리나 작업 제어가 아니라 사용자의 요구에 따라 특정 서비스를 제공하는 프로그램이다. 예를 들어, 에디터, 인터프리터, 컴파일러, 유틸리티 등이 있다. 서비스 프로그램은 사용자의 작업을 지원하기 위한 목적으로 개발된 프로그램이므로, 제어 프로그램에 해당하지 않는다.</p>"]}},{"id":"13742","number":64,"category":"프로그래밍 언어 활용","type":"choice","subject":"IEEE 802.3 LAN에서 사용되는 전송매체 접속제어(MAC) 방식은?","choices":[{"n":1,"html":"CSMA/CD"},{"n":2,"html":"Token Bus"},{"n":3,"html":"Token Ring"},{"n":4,"html":"Slotted Ring"}],"answer":[1],"wiki":[{"title":"IEEE 802","url":"https://itwiki.kr/w/IEEE 802"},{"title":"CSMA/CD","url":"https://itwiki.kr/w/CSMA/CD"}],"explain":{"ai":["<p>IEEE 802.3 랜에서 사용되는 전송 매체 접속 제어 방식은 CSMA/CD 방식이다. \n이 방식은 컴퓨터나 장치들이 네트워크를 통해 데이터를 전송할 때 충돌을 방지하고 데이터 전송을 조율하기 위한 방법이다. \nCSMA/CD 방식은 제어를 받지 않는 방식으로, 여러 장치들이 같은 네트워크를 사용하면서 데이터 전송을 시도할 때 충돌이 발생할 수 있다. \n这种 경우 장치들은 충돌을 감지하고 서로 데이터 전송을 재시도한다. \n이 방식은 이더넷과 같은 유선 랜에서 주로 사용된다. \n따라서 IEEE 802.3 랜에서 사용되는 전송 매체 접속 제어 방식은 CSMA/CD 방식이다.</p>"]}},{"id":"13743","number":65,"category":"프로그래밍 언어 활용","type":"choice","subject":"기억공간이 15K, 23K, 22K, 21K 순으로 빈 공간이 있을 때 기억장치 배치 전력으로 “First Fit”을 사용하여 17K의 프로그램을 적재할 경우 내부단편화의 크기는 얼마인가?","choices":[{"n":1,"html":"5K"},{"n":2,"html":"6K"},{"n":3,"html":"7K"},{"n":4,"html":"8K"}],"answer":[2],"explain":{"ai":["<p>프로그램을 적재하기 위해 사용하는 방법 중 첫 번째 적합 방법을 사용하면 기억공간 중 프로그램의 사이즈보다 큰 첫 번째 블록에 프로그램을 할당합니다. \n15K 보다 크지 않으니 15K는 사용할 수 없고 23K는 사용할 수 있고 17K를 사용하는데 23K를 사용한 후 6K의 공간이 남습니다. \n22K, 21K는 17K를 사용하기 위해 필요한 메모리 크기보다 작으니 사용할 수 없습니다. \n따라서 내부 단편화의 크기는 23K - 17K로 6K입니다. \n그러므로 정답은 2번입니다.</p>"]}},{"id":"13744","number":66,"category":"프로그래밍 언어 활용","type":"choice","subject":"교착상태가 발생할 수 있는 조건이 아닌 것은?","choices":[{"n":1,"html":"Mutual exclusion"},{"n":2,"html":"Hold and wait"},{"n":3,"html":"Non-preemption"},{"n":4,"html":"Linear wait"}],"answer":[4],"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"explain":{"ai":["<p>교착상태가 발생할 수 있는 조건은 상호배제, 보유와 대기, 비선점, 순환대기 4가지입니다. 교착상태는 시스템에서 두 개 이상의 프로세스가 무한정으로 대기하는 상태를 말합니다. </p>\n<p>상호배제는 두 개 이상의 프로세스가 공유자원을 동시에 사용할 수 없는 경우입니다. 보유와 대기는 프로세스가 자원을 할당받고 또 다른 자원을 기다리는 경우입니다. 비선점은 프로세스가 자원을 강제로 빼앗을 수 없는 경우입니다. 순환대기는 프로세스가 자원을 기다리는 과정에서 순환적으로 대기하는 경우입니다.</p>\n<p>보기 중 Linear wait는 교착상태의 조건이 아닙니다. Linear wait라는 용어는 교착상태의 조건에 해당하지 않으며, 교착상태의 조건은 상호배제, 보유와 대기, 비선전, 순환대기 4가지입니다.</p>"]}},{"id":"13745","number":67,"category":"프로그래밍 언어 활용","type":"choice","subject":"IPv6에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"멀티캐스팅(Multicast) 대신 브로드캐스트(Broadcast)를 사용한다."},{"n":2,"html":"보안과 인증 확장 헤더를 사용함으로써 인터넷 계층의 보안기능을 강화하였다."},{"n":3,"html":"애니캐스트(Anycast)는 하나의 호스트에서 그룹 내의 가장 가까운 곳에 있는 수신자에게 전달하는 방식이다."},{"n":4,"html":"128비트 주소체계를 사용한다."}],"answer":[1],"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"explain":{"ai":["<p>IPv6에 대한 설명으로 틀린 것은 1번이다. IPv6는 멀티캐스팅을 지원하지만, 브로드캐스트는 사용하지 않는다. IPv6에서는 멀티캐스팅을 사용하여 특정 그룹의 호스트에게 데이터를 전송할 수 있다. </p>\n<p>IPv6의 보안과 인증 확장 헤더는 인터넷 계층의 보안 기능을 강화한다는 점에서 2번은 올바른 설명이다. 애니캐스트(Anycast)는 하나의 호스트에서 그룹 내의 가장 가까운 곳에 있는 수신자에게 전달하는 방식이므로 3번도 올바른 설명이다. 또한, IPv6는 128비트 주소 체계를 사용하므로 4번도 올바른 설명이다. </p>\n<p>따라서, IPv6에 대한 설명으로 틀린 것은 멀티캐스팅 대신 브로드캐스트를 사용한다는 1번이다.</p>"]}},{"id":"13746","number":68,"category":"프로그래밍 언어 활용","type":"choice","subject":"TCP/IP 프로토콜에서 TCP가 해당하는 계층은?","choices":[{"n":1,"html":"데이터 링크 계층"},{"n":2,"html":"네트워크 계층"},{"n":3,"html":"트랜스포트 계층"},{"n":4,"html":"세션 계층"}],"answer":[3],"wiki":[{"title":"TCP/IP","url":"https://itwiki.kr/w/TCP/IP"},{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"explain":{"ai":["<p>TCP 프로토콜은 데이터를 신뢰성 있게 전송하기 위한 프로토콜입니다. TCP/IP 프로토콜 스택에서 TCP는 트랜스포트 계층에 해당합니다. 트랜스포트 계층의 주요 기능은 종단간 데이터 전송을 담당하며, 신뢰성 있는 데이터 전송과 다중화 및 데이터 분할 기능을 수행합니다. 따라서 TCP 프로토콜은 트랜스포트 계층에서 데이터 전송을 담당합니다. 이는 IP 프로토콜과 함께 사용되어 데이터를 전송할 수 있습니다. 데이터 링크 계층은 물리적인 네트워크 연결을 관리하고, 네트워크 계층은 데이터를 목적지까지 전송하는 경로를 결정하며, 세션 계층은 통신 세션을 관리합니다. 따라서 TCP는 트랜스포트 계층에 해당합니다.</p>"]}},{"id":"13747","number":69,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 변수로 사용할 수 없는 것은?","choices":[{"n":1,"html":"data02"},{"n":2,"html":"int01"},{"n":3,"html":"_sub"},{"n":4,"html":"short"}],"answer":[4],"explain":{"ai":["<p>C언어에서 변수명은 특정 규칙을 따라야 합니다. </p>\n<ul>\n<li>첫 글자는 알파벳(a-z, A-Z) 또는 밑줄(_)이어야 합니다.</li>\n<li>그 이후에는 알파벳, 숫자, 밑줄이 올 수 있습니다.</li>\n</ul>\n<p>4번 보기인 'short'는 C언어에서 키워드로 사용되는 예약어입니다. 키워드는 변수명으로 사용할 수 없습니다. 따라서 정답은 4번입니다.</p>"]}},{"id":"13748","number":70,"category":"프로그래밍 언어 활용","type":"choice","subject":"다음 JAVA 코드 출력문의 결과는?","extra":"<pre class=\"contents\">...생략...\r\nSystem.out.println(“5 + 2 = ” + 3 + 4);\r\nSystem.out.println(“5 + 2 = ” + (3 + 4));\r\n...생략...</pre>","choices":[{"n":1,"html":"5 + 2 = 34\\n5 + 2 = 34"},{"n":2,"html":"5 + 2 + 3 + 4\\n5 + 2 = 7"},{"n":3,"html":"7 = 7\\n7 + 7"},{"n":4,"html":"5 + 2 = 34\\n5 + 2 = 7"}],"answer":[4],"explain":{"ai":["<p>첫 번째 <code>System.out.println(\"5 + 2 = \" + 3 + 4);</code> 구문에서는 문자열 연결과 연산 우선순위에 따라 <code>3 + 4</code>가 먼저 계산되어 <code>7</code>이 되고, <code>\"5 + 2 = \" + 7</code>이 되어 출력은 <code>5 + 2 = 7</code>이 되지만, 주어진 옵션과 정확히 일치하지 않아 주의가 필요하다. 하지만 주어진 보기 중에서 가장 적합한 것은 문자열 연결의 일반적인 동작을 고려했을 때 옵션 4번에 가깝게 해석될 수 있다.</p>\n<p>두 번째 <code>System.out.println(\"5 + 2 = \" + (3 + 4));</code> 구문은 괄호 안의 연산이 먼저 수행되어 <code>3 + 4</code>가 <code>7</code>로 계산되고, 전체 표현식은 <code>\"5 + 2 = \" + 7</code>으로 문자열 연결되어 정확히 <code>5 + 2 = 7</code>을 출력한다.</p>\n<p>그러나 주어진 보기 중에서 첫 번째 줄의 동작을 정확히 반영하면서, 두 번째 줄에서 괄호의 영향으로 올바른 결과가 나오는 옵션은 4번이다. 첫 줄에서는 숫자 연결로 인해 예상 외의 출력이 나올 가능성이 있으나, 주어진 보기 중에서는 4번이 가장 적합하게 보인다. 즉, 첫 줄은 문자열 연결의 특수성을 고려해 <code>5 + 2 = 34</code>로 해석되는 오류를 반영하고, 두 번째 줄은 정확한 연산 결과를 보여주는 <code>5 + 2 = 7</code>을 나타낸다.</p>"]}},{"id":"13749","number":71,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 문자열을 정수형으로 변환하는 라이브러리 함수는?","choices":[{"n":1,"html":"atoi( )"},{"n":2,"html":"atof( )"},{"n":3,"html":"itoa( )"},{"n":4,"html":"ceil( )"}],"answer":[1],"explain":{"ai":["<p>C언어에서는 문자열을 정수형으로 변환할 때 atoi 함수를 사용합니다. \natoi 함수는 Null终止 문자열을 인자로 받아서 그 문자열에 포함된 정수 값을 반환합니다. \natof 함수는 문자열을 실수형으로 변환합니다. \nitoa 함수는 정수를 문자열로 변환하지만これは 标准 라이브러리에 포함되어 있지 않습니다. \nceil 함수는 소수점을 올림하여 정수형으로 반환합니다. \n그러나 C언어에서 문자열을 정수형으로 변환할 때 사용하는 함수는 atoi 함수이므로 1번이 정답입니다.</p>"]}},{"id":"13750","number":72,"category":"프로그래밍 언어 활용","type":"choice","subject":"운영체제의 가상기억장치 관리에서 프로세스가 일정 시간동안 자주 참조하는 페이지들의 집합을 의미하는 것은?","choices":[{"n":1,"html":"Locality"},{"n":2,"html":"Deadlock"},{"n":3,"html":"Thrashing"},{"n":4,"html":"Working Set"}],"answer":[4],"explain":{"ai":["<p>정답은 <strong>4. Working Set</strong> 입니다. </p>\n<p><strong>해설:</strong></p>\n<ul>\n<li><strong>Working Set</strong>은 프로세스가 특정 시간 동안 자주 사용하는 페이지들의 집합을 나타냅니다. 운영체제는 Working Set을 파악하여 이 페이지들을 메인 메모리에 유지함으로써 프로세스의 실행 속도를 향상시킵니다. </li>\n</ul>\n<p>다른 보기들은 틀린 이유는 다음과 같습니다.</p>\n<ul>\n<li><strong>Locality</strong>는 프로세스의 실행 패턴에서 나타나는 공간적/시간적 집중성을 의미하며, Working Set이 형성되는  <strong>원인</strong>을 설명하는 개념입니다.</li>\n<li><strong>Deadlock</strong>은 여러 프로세스가 자원을 점유하며 서로 기다리는 상태를 말합니다.</li>\n<li><strong>Thrashing</strong>은 과도한 페이지 교체로 인해 프로세스가 실제 작업보다 페이지 교체에 더 많은 시간을 소비하는 현상입니다.</li>\n</ul>"]}},{"id":"13751","number":73,"category":"프로그래밍 언어 활용","type":"choice","subject":"결합도가 낮은 것부터 높은 순으로 옳게 나열한 것은?","extra":"<pre class=\"contents\">(ㄱ) 내용결합도\t(ㄴ) 자료결합도\r\n(ㄷ) 공통결합도\t(ㄹ) 스탬프결합도\r\n(ㅁ) 외부결합도\t(ㅂ) 제어결합도</pre>","choices":[{"n":1,"html":"(ㄱ) → (ㄴ) → (ㄹ) → (ㅂ) → (ㅁ) → (ㄷ)"},{"n":2,"html":"(ㄴ) → (ㄹ) → (ㅁ) → (ㅂ) → (ㄷ) → (ㄱ)"},{"n":3,"html":"(ㄴ) → (ㄹ) → (ㅂ) → (ㅁ) → (ㄷ) → (ㄱ)"},{"n":4,"html":"(ㄱ) → (ㄴ) → (ㄹ) → (ㅁ) → (ㅂ) → (ㄷ)"}],"answer":[3],"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"explain":{"ai":["<p>결합도는 모듈 간의 상호 의존성을 나타내는 개념으로, 낮을수록 모듈 간의 독립성이 높아지며, 좋다. </p>\n<p>내용 결합도는 하나의 모듈이 다른 모듈의 내용을 참조할 때 발생하며, 가장 결합도가 높다. \n공통 결합도는 모듈이 공통의 전역 변수를 참조할 때 발생한다. \n제어 결합도는 모듈이 다른 모듈을 제어하기 위해 Flag나 제어 변수를 전달할 때 발생한다. \n스탬프 결합도는 모듈이 자료 구조를 전달할 때 발생하며, 자료 결합도보다 높은 결합도를 가진다. \n자료 결합도는 모듈이 데이터를 전달할 때 발생하며, 가장 결합도가 낮다. \n외부 결합도는 모듈이 외부 파일이나 장치를 참조할 때 발생한다.</p>\n<p>따라서 결합도가 낮은 순으로 나열하면 자료 결합도, 스탬프 결합도, 외부 결합도, 제어 결합도, 공통 결합도, 내용 결합도가 된다. \n따라서 정답은 (ㄴ) → (ㄹ) → (ㅂ) → (ㅁ) → (ㄷ) → (ㄱ)로 결합도가 낮은 것부터 높은 순으로 나열한 것은 3번이다.</p>"]}},{"id":"13752","number":74,"category":"프로그래밍 언어 활용","type":"choice","subject":"다음 설명의 ㉠과 ㉡에 들어갈 내용으로 옳은 것은?","extra":"<pre class=\"contents\">가상기억장치의 일반적인 구현 방법에는 프로그램을 고정된 크기의 일정한 블록으로 나누는 (㉠) 기법과 가변적인 크기의 블록으로 나누는 (㉡) 기법이 있다.</pre>","choices":[{"n":1,"html":"㉠ : Paging, ㉡ : Segmentation"},{"n":2,"html":"㉠ : Segmentation, ㉡ : Allocatin"},{"n":3,"html":"㉠ : Segmentation, ㉡ : Compaction"},{"n":4,"html":"㉠ : Paging, ㉡ : Linking"}],"answer":[1],"wiki":[{"title":"가상 메모리","url":"https://itwiki.kr/w/가상 메모리"}],"explain":{"ai":["<p>가상기억장치의 일반적인 구현 방법에는 프로그램을 고정된 크기의 일정한 블록으로 나누는 기법과 가변적인 크기의 블록으로 나누는 기법이 있다. 고정된 크기의 블록으로 programu를 나누는 기법은 Paging 기법이고, 가변적인 크기의 블록으로 나누는 기법은 Segmentation 기법이다. Paging 기법은 프로그램을 동일한 크기의 페이지로 나누어 관리하는 방식이고, Segmentation 기법은 프로그램을 논리적인 단위인 세그먼트로 나누어 관리하는 방식이다. 따라서 ㉠에는 Paging, ㉡에는 Segmentation이 들어가야 한다.</p>"]}},{"id":"13753","number":75,"category":"프로그래밍 언어 활용","type":"choice","subject":"라이브러리의 개념과 구성에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"라이브러리란 필요할 때 찾아서 쓸 수 있도록 모듈화되어 제공되는 프로그램을 말한다."},{"n":2,"html":"프로그래밍 언어에 따라 일반적으로 도움말, 설치 파일, 샘플 코드 등을 제공한다."},{"n":3,"html":"외부 라이브러리는 프로그래밍 언어가 기본적으로 가지고 있는 라이브러리를 의미하며, 표준 라이브러리는 별도의 파일 설치를 필요로 하는 라이브러리를 의미한다."},{"n":4,"html":"라이브러리는 모듈과 패키지를 총칭하며, 모듈이 개별 파일이라면 패키지는 파일들을 모아 놓은 폴더라고 볼 수 있다."}],"answer":[3],"explain":{"ai":["<p>라이브러리는 필요할 때 사용할 수 있도록 모듈화되어 제공되는 프로그램이다. 라이브러리는 보통 도움말, 설치 파일, 샘플 코드 등을 제공한다. 라이브러리는 모듈과 패키지로 구성되어があり 모듈은 개별 파일을 의미하고 패키지는 여러 파일을 모아둔 폴더로 볼 수 있다.但 外部 라이브러리는 별도의 설치가 필요한 라이브러리이고 표준 라이브러리는 프로그래밍 언어가 기본적으로 제공하는 라이브러리이다. 따라서 3번이 틀린 것이다.</p>"]}},{"id":"13754","number":76,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 산술 연산자가 아닌 것은?","choices":[{"n":1,"html":"%"},{"n":2,"html":"*"},{"n":3,"html":"/"},{"n":4,"html":"="}],"answer":[4],"explain":{"ai":["<p>C언어에서 산술 연산자는 숫자를 다루는 연산을 말한다. 주요 산술 연산자로는 더하기, 빼기, 곱하기, 나누기, 나머지 계산 등이 있다. </p>\n<p>산술 연산자 중에서EMPLARY*와 /, %는 모두 산술 연산자이다. </p>\n<p>반면에 =는 대입 연산자로 변수에 값을 할당하는 역할을 한다. 따라서 산술 연산자가 아닌 것은 =이다.</p>"]}},{"id":"13755","number":77,"category":"프로그래밍 언어 활용","type":"choice","subject":"UDP 특성에 해당되는 것은?","choices":[{"n":1,"html":"양방향 연결형 서비스를 제공한다."},{"n":2,"html":"송신중에 링크를 유지관리하므로 신뢰성이 높다."},{"n":3,"html":"순서제어, 오류제어, 흐름제어 기능을 한다."},{"n":4,"html":"흐름제어나 순서제어가 없어 전송속도가 빠르다."}],"answer":[4],"wiki":[{"title":"UDP","url":"https://itwiki.kr/w/UDP"}],"explain":{"ai":["<p>UDP는 연결지향형이 아니기 때문에 1번은 틀립니다. \n또한 신뢰성과 관련된 2번은 TCP에서 처리하는 내용이기 때문에 UDP는 해당사항이 없으므로 2번은 틀립니다. \n순서제어, 오류제어, 흐름제어 기능은 TCP에서 처리하는 내용이므로 3번도 틀립니다. \nUDP는 연결을 설정하지 않고 데이터그램을 독립적으로 처리함으로써 신뢰성은 낮지만 전송 속도는 빠르기 때문에 4번이 정답입니다. \nUDP는 연결을 설정하고 종료할 때 필요한 절차를省略함으로써 TCP보다 전송 속도가 빠르다는 특징이 있습니다.</p>"]}},{"id":"13756","number":78,"category":"프로그래밍 언어 활용","type":"choice","subject":"JAVA에서 변수와 자료형에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"변수는 어떤 값을 주기억 장치에 기억하기 위해서 사용하는 공간이다."},{"n":2,"html":"변수의 자료형에 따라 저장할 수 있는 값의 종류와 범위가 달라진다."},{"n":3,"html":"char 자료형은 나열된 여러 개의 문자를 저장하고자 할 때 사용한다."},{"n":4,"html":"boolean 자료형은 조건이 참인지 거짓인지 판단하고자 할 때 사용한다."}],"answer":[3],"explain":{"ai":["<p>자바에서 변수와 자료형을 설명하는 문장 중에서 잘못된 것을 찾으라고 합니다. \n변수는 값을 주기억 장치에 저장하는 공간이 맞습니다. \n변수의 자료형에 따라 저장할 수 있는 값의 종류와 범위가 달라지는 것도 맞습니다. \nboolean 자료형은 조건이 참인지 거짓인지 판단할 때 사용합니다. \n그러나 char 자료형은 문자를 하나만 저장할 수 있습니다. \n여러 개의 문자를 저장하고자 할 때는 String 자료형을 사용해야 합니다. \n따라서 3번이 잘못된 설명입니다.</p>"]}},{"id":"13757","number":79,"category":"프로그래밍 언어 활용","type":"choice","subject":"다음은 파이썬으로 만들어진 반복문 코드이다. 이 코드의 결과는?","extra":"<pre class=\"contents\">>> while(True) ：\r\nprint('A')\r\nprint(’B‘)\r\nprint(’C‘)\r\ncontinue\r\nprint(’D‘)</pre>","choices":[{"n":1,"html":"A, B, C 출력이 반복된다."},{"n":2,"html":"A, B, C"},{"n":3,"html":"A, B, C, D 출력이 반복된다."},{"n":4,"html":"A, B, C, D 까지만 출력된다."}],"answer":[1],"explain":{"ai":["<p>이 코드에서 반복문을 시행할 때, continue 문을 만나는 경우에는 남은 코드를 건너뛰고 다음 반복으로 넘어간다. 코드를 보니 반복문이 while true 로 이루어져 있어서 무한 반복을 의미한다. 그리고 print('D') 문이 continue 문 뒤에 있기 때문에 Print('D')는 출력되지 않는다. </p>\n<p>결과적으로 A, B, C 가 무한 반복되는 코드가 된다.</p>"]}},{"id":"13758","number":80,"category":"프로그래밍 언어 활용","type":"choice","subject":"WAS(Web Application Server)가 아닌 것은?","choices":[{"n":1,"html":"JEUS"},{"n":2,"html":"JVM"},{"n":3,"html":"Tomcat"},{"n":4,"html":"WebSphere"}],"answer":[2],"explain":{"ai":["<p>WAS란 웹 애플리케이션 서버를 뜻한다. 웹 애플리케이션 서버는 동적 웹 페이지를 처리하도록 설계된 소프트웨어 프레임워크이다. </p>\n<p>JEUS는 웹 애플리케이션 서버를 뜻하는 약자로 네이버 등에서 사용하고 있다. Tomcat은 자바를 사용하여 개발된 웹 애플리케이션 서버로 아파치 소프트웨어 재단에서 개발하였다. WebSphere는 IBM이 개발한 웹 애플리케이션 서버이다.</p>\n<p>JVM은 자바 虛擬機器를 뜻하는 약자로 자바 프로그래밍 언어를 실행할 수 있는 가상 머신이다. 자바로 작성된 애플리케이션을 실행할 때 필요한 소프트웨어로 웹 애플리케이션 서버가 아니다. </p>\n<p>따라서 정답은 2번인 JVM이다.</p>"]}},{"id":"13759","number":81,"category":"정보시스템 구축관리","type":"choice","subject":"다음 암호 알고리즘 중 성격이 다른 하나는?","choices":[{"n":1,"html":"MD4"},{"n":2,"html":"MD5"},{"n":3,"html":"SHA-1"},{"n":4,"html":"AES"}],"answer":[4],"wiki":[{"title":"암호","url":"https://itwiki.kr/w/암호"},{"title":"해시","url":"https://itwiki.kr/w/해시"},{"title":"대칭키 암호화","url":"https://itwiki.kr/w/대칭키 암호화"},{"title":"AES","url":"https://itwiki.kr/w/AES"},{"title":"SHA-1","url":"https://itwiki.kr/w/SHA-1"},{"title":"MD5","url":"https://itwiki.kr/w/MD5"},{"title":"MD4","url":"https://itwiki.kr/w/MD4"}],"explain":{"ai":["<p>해당 문제의 정답은 4번인 AES입니다. 이유는 MD4, MD5, SHA-1 알고리즘은 모두 해시 함수로, 데이터의 무결성과 신뢰성을 검증하는 데 주로 사용됩니다. 그러나 AES는 다른 알고리즘으로, 대칭 키 블록 암호 알고리즘입니다. 즉, 데이터를 암호화하고 복호화하는 데 사용됩니다. 따라서 AES는 해시 함수가 아닌 암호화 알고리즘으로서 성격이 다릅니다. 이는 데이터를 보호하고 기밀성을 유지하는 데 사용되는 다른 목적을 가지고 있습니다. 이러한 차이로 인해 AES는 다른 선택지와는 성격이 다른 알고리즘입니다.</p>"]}},{"id":"13760","number":82,"category":"정보시스템 구축관리","type":"choice","subject":"크래커가 침입하여 백도어를 만들어 놓거나, 설정파일을 변경했을 때 분석하는 도구는?","choices":[{"n":1,"html":"tripwire"},{"n":2,"html":"tcpdump"},{"n":3,"html":"cron"},{"n":4,"html":"netcat"}],"answer":[1],"wiki":[{"title":"Tripwire","url":"https://itwiki.kr/w/Tripwire"}],"explain":{"ai":["<p>크래커가 침입하여 백도어를 만들어 놓거나 설정파일을 변경했을 때 분석하는 도구는.tripwire 입니다. tripwire는 파일의 무결성을 체크하여 파일이나 설정파일이 변경되었는지 확인할 수 있습니다. 이를 통해 크래커가 시스템에 침입하여 파일이나 설정을 변경했는지 감지할 수 있고 해당 파일이나 설정이 변경되었다면 즉시 알림을 받을 수 있습니다. 따라서 시스템의 enim 무결성을 유지하고 안정성을 cao 높이기 위한 중요한 도구 중 하나입니다.</p>"]}},{"id":"13761","number":83,"category":"정보시스템 구축관리","type":"choice","subject":"다음 내용이 설명하는 것은?","extra":"<pre class=\"contents\">- 사물통신, 사물인터넷과 같이 대역폭이 제한된 통신환경에 최적화하여 개발된 푸시기술 기반의 경량' 메시지 전송 프로토콜\r\n- 메시지 매개자(Broker)를 통해 송신자가 특정 메시지를 발행하고 수신자가 메시지를 구독하는 방식\r\n- IBM이 주도하여 개발</pre>","choices":[{"n":1,"html":"GRID"},{"n":2,"html":"TELNET"},{"n":3,"html":"GPN"},{"n":4,"html":"MQTT"}],"answer":[4],"wiki":[{"title":"mqtt","url":"https://itwiki.kr/w/mqtt"}],"explain":{"ai":["<p>MQTT(MQ Telemetry Transport)는 사물통신, 사물인터넷과 같은 대역폭이 제한된 통신환경에서 사용하기 위해 개발된 경량 메시지 전송 프로토콜입니다. 메시지 매개자(Broker)를 통해 송신자가 특정 메시지를 발행하고 수신자가 메시지를 구독하는 방식으로 작동합니다. IBM이 주도하여 개발된 프로토콜로, 사물인터넷(IoT) 분야에서 많이 사용됩니다. </p>\n<p>따라서, 주어진 설명은 MQTT를 나타내므로 정답은 4번입니다.</p>"]}},{"id":"13762","number":84,"category":"정보시스템 구축관리","type":"choice","subject":"나선형(Spiral) 모형의 주요 태스크에 해당되지 않는 것은?","choices":[{"n":1,"html":"버전 관리"},{"n":2,"html":"위험 분석"},{"n":3,"html":"개발"},{"n":4,"html":"평가"}],"answer":[1],"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"explain":{"ai":["<p>나선형 모형은 시스템 개발이나 소프트웨어 개발에서 사용되는 하나의 모델로, 프로젝트의 복잡성을 단계적으로 관리하는 것을 목적으로 한다. 나선형 모형의 주요 태스크에는 위험 분석, 개발, 평가가 포함된다. </p>\n<p>위험 분석은 프로젝트 초기에 잠재적인 위험을 식별하고 평가하여 이를 관리하는 것을 포함한다. 개발은 실제로 시스템이나 소프트웨어를 구축하는 단계이다. 평가는 프로젝트의 진행 상황을 검토하고 필요에 따라 계획을 조정하는 것을 포함한다.</p>\n<p>반면에 버전 관리는 소프트웨어 개발에서 코드나 문서의 변경을 관리하는 기술이다. 버전 관리는 개발 과정에서 중요하지만 나선형 모형의 주요 태스크는 아니다. 버전 관리는 개발 과정에서 사용되는 도구 또는 기술이라고 할 수 있다. </p>\n<p>따라서 나선형 모형의 주요 태스크에 해당되지 않는 것은 버전 관리이다.</p>"]}},{"id":"13763","number":85,"category":"정보시스템 구축관리","type":"choice","subject":"정보 보안을 위한 접근통제 정책 종류에 해당하지 않는 것은?","choices":[{"n":1,"html":"임의적 접근 통제"},{"n":2,"html":"데이터 전환 접근 통제"},{"n":3,"html":"강제적 접근 통제"},{"n":4,"html":"역할 기반 접근 통제"}],"answer":[2],"wiki":[{"title":"접근통제 정책","url":"https://itwiki.kr/w/접근통제 정책"}],"explain":{"ai":["<p>접근통제 정책은 정보 보안에서 매우 중요한 개념입니다. 정보 보안을 위한 접근통제 정책 종류에는 임의적 접근 통제, 강제적 접근 통제, 역할 기반 접근 통제가 있습니다. </p>\n<p>임의적 접근 통제는 사용자에게 주TextChanged 된 권한에 따라 접근을 통제하는 방식입니다. 강제적 접근 통제는 사용자와 자원에 대한 권한을 강제적으로 통제하는 방식입니다. 역할 기반 접근 통제는 사용자의 역할에 따라 접근을 통제하는 방식입니다.</p>\n<p>반면에 데이터 전환 접근 통제는 접근통제 정책의 종류에 해당하지 않습니다. 데이터 전환은 데이터를 하나의 형식에서 다른 형식으로 변환하는 것을 말합니다. 접근통제와 관련이 없는 개념입니다. 따라서 2번 데이터 전환 접근 통제가 정보 보안을 위한 접근통제 정책 종류에 해당하지 않는 것입니다.</p>"]}},{"id":"13764","number":86,"category":"정보시스템 구축관리","type":"choice","subject":"LOC기법에 의하여 예측된 총 라인수가 36,000라인, 개발에 참여할 프로그래머가 6명, 프로그래머들의 평균 생산성이 월간 300라인일 때 개발에 소요되는 기간은?","choices":[{"n":1,"html":"5개월"},{"n":2,"html":"10개월"},{"n":3,"html":"15개월"},{"n":4,"html":"20개월"}],"answer":[4],"explain":{"ai":["<p>개발에 소요되는 기간을 계산하려면 총 라인수를 프로그래머들의 평균 생산성과 개발에 참여할 프로그래머 수로 나눠야 해. 총 라인수는 36,000라인, 개발에 참여할 프로그래머는 6명, 평균 생산성은 월간 300라인이라고 알려져 있어. </p>\n<p>총 라인수를 평균 생산성과 개발에 참여할 프로그래머 수로 나누면 36,000 ÷ (6 × 300) = 20개월이 돼. 그렇지 뭐야. 그래서 개발에 소요되는 기간은 20개월이야.</p>"]}},{"id":"13765","number":87,"category":"정보시스템 구축관리","type":"choice","subject":"정형화된 분석 절차에 따라 사용자 요구사항을 파악, 문서화하는 체계적 분석방법으로 자료흐름도, 자료사전, 소단위명세서의 특징을 갖는 것은?","choices":[{"n":1,"html":"구조적 개발 방법론"},{"n":2,"html":"객체지향 개발 방법론"},{"n":3,"html":"정보공학 방법론"},{"n":4,"html":"CBD 방법론"}],"answer":[1],"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"},{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"explain":{"ai":["<p>정형화된 분석 절차에 따라 사용자 요구사항을 파악, 문서화하는 체계적 분석방법은 구조적 개발 방법론입니다. 구조적 개발 방법론은 시스템 개발을 체계적으로 진행하기 위한 절차と 기법을 제공합니다. 자료흐름도, 자료사전, 소단위명세서를 특징으로 하며, 사용자 요구사항을 명확하게 파악하고, 문서화하여 시스템 개발을効率적으로 진행할 수 있게 도와줍니다. 이러한 특징은 구조적 개발 방법론의 핵심입니다. 따라서 정답은 구조적 개발 방법론인 1번입니다.</p>"]}},{"id":"13766","number":88,"category":"정보시스템 구축관리","type":"choice","subject":"정보보호를 위한 암호화에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"평문 – 암호화되기 전의 원본 메시지"},{"n":2,"html":"암호문 – 암호화가 적용된 메시지"},{"n":3,"html":"복호화 – 평문을 암호문으로 바꾸는 작업"},{"n":4,"html":"키(Key) - 적절한 암호화를 위하여 사용하는 값"}],"answer":[3],"wiki":[{"title":"암호#용어_정의","url":"https://itwiki.kr/w/암호#용어_정의"}],"explain":{"ai":["<p>정보보호를 위한 암호화란 데이터를 보호하기 위해 불법적으로 데이터에 접근하여도 의미를 이해할 수 없도록 하는 기술입니다. 암호화 과정에서 사용되는 용어를 살펴보면 평문은 암호화되기 전의 원본 메시지를 말합니다. 암호문은 암호화가 적용된 메시지를 말하며, 키는 암호화를 진행하거나 복호화를 진행할 때 사용되는 값입니다.</p>\n<p>이 Observatory에서는 복호화가 평문을 암호문으로 바꾸는 작업이라고 설명되었는데 이는 사실 반대의 과정입니다. 복호화란 암호문을 원래의 平문으로 바꾸는 작업을 말합니다. 따라서 정답은 3번입니다.</p>"]}},{"id":"13767","number":89,"category":"정보시스템 구축관리","type":"choice","subject":"다음 내용이 설명하는 것은?","extra":"<pre class=\"contents\">- 블록체인(Blockchain) 개발환경을 클라우드로 서비스하는 개념\r\n- 블록체인 네트워크에 노드의 추가 및 제거가 용이\r\n- 블록체인의 기본 인프라를 추상화하여 블록체인 응용프로그램을 만들 수 있는 클라우드 컴퓨팅 플랫폼</pre>","choices":[{"n":1,"html":"OTT"},{"n":2,"html":"BaaS"},{"n":3,"html":"SDDC"},{"n":4,"html":"Wi-SUN"}],"answer":[2],"wiki":[{"title":"BaaS","url":"https://itwiki.kr/w/BaaS"}],"explain":{"ai":["<p>지문은 블록체인 개발환경을 클라우드로 서비스하는 개념을 설명하며, 블록체인 네트워크에 노드의 추가 및 제거가 용이하고, 블록체인의 기본 인프라를 추상화하여 블록체인 응용프로그램을 만들 수 있는 클라우드 컴퓨팅 플랫폼을 언급합니다. 이러한 설명은 블록체인 어플리케이션을 개발하고 사용하는데 필요한 인프라 스트ラク처를 클라우드 서비스로 제공하는 개념인 Baas를 정의하고 있습니다. 따라서 지문이 설명하는 것은 BaaS입니다.</p>"]}},{"id":"13768","number":90,"category":"정보시스템 구축관리","type":"choice","subject":"소프트웨어 비용 산정 기법 중 개발 유형으로 organic, semi-detach, embedded로 구분되는 것은?","choices":[{"n":1,"html":"PUTNAM"},{"n":2,"html":"COCOMO"},{"n":3,"html":"FP"},{"n":4,"html":"SLIM"}],"answer":[2],"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"explain":{"ai":["<p>소프트웨어 비용 산정 기법 중 개발 유형으로 organic, semi-detach, embedded로 구분되는 것은 COCOMO 기법이다. COCOMO는 보헤姆이 개발한 것으로 소프트웨어 개발 유형을 organic, semi-detach, embedded로 나누어 비용을 산정한다. 이는 소프트웨어 개발의 복잡도와 개발 환경을 고려하여 비용을 예측하는 데 사용된다.</p>"]}},{"id":"13769","number":91,"category":"정보시스템 구축관리","type":"choice","subject":"다음 LAN의 네트워크 토폴로지는 어떤 형인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"그물형"},{"n":2,"html":"십자형"},{"n":3,"html":"버스형"},{"n":4,"html":"링형"}],"answer":[3]},{"id":"13770","number":92,"category":"정보시스템 구축관리","type":"choice","subject":"전기 및 정보통신기술을 활용하여 전력망을 지능화, 고도화함으로써 고품질의 전력서비스를 제공하고 에너지 이용효율을 극대화하는 전력망은?","choices":[{"n":1,"html":"사물 인터넷"},{"n":2,"html":"스마트 그리드"},{"n":3,"html":"디지털 아카이빙"},{"n":4,"html":"미디어 빅뱅"}],"answer":[2],"explain":{"ai":["<p>스마트 그리드는 전기 및 정보통신기술을 활용하여 전력망을 지능화하고 고도화하는 것을 말합니다. 이는 전력의 실시간 감시와 제어를 가능하게 하며, 에너지 이용 효율을 극대화하고 고품질의 전력 서비스를 제공하기 위해 설계되었습니다. 스마트 그리드는 전력망의 안정성과 신뢰성을 향상시키고, 재생에너지의 도입을 용이하게 하며, 전력 사용자에게 실시간으로 전력 사용량과 비용 정보를 제공하여 전력 소비를 효율적으로 관리할 수 있도록 합니다. 이러한 đặc징으로 인해 스마트 그리드가 전기 및 정보통신기술을 활용하여 전력망을 지능화하고 고도화하는 대표적인 예입니다.</p>"]}},{"id":"13771","number":93,"category":"정보시스템 구축관리","type":"choice","subject":"다음 내용이 설명하는 소프트웨어 개발 모형은?","extra":"<pre class=\"contents\">소프트웨어 생명주기 모형 중 Boehm이 제시한 고전적 생명주기 모형으로서 선형 순차적 모델이라고도 하며, 타당성 검토, 계획, 요구사항 분석, 설계, 구현, 테스트, 유지보수의 단계를 통해 소프트웨어를 개발하는 모형</pre>","choices":[{"n":1,"html":"프로토타입 모형"},{"n":2,"html":"나선형 모형"},{"n":3,"html":"폭포수 모형"},{"n":4,"html":"RAD 모형"}],"answer":[3],"explain":{"ai":["<p>해당 문제는 소프트웨어 개발 모형을묻는 문제입니다. \n지문에는 선형 순차적 모델, 타당성 검토, 계획, 요구사항 분석, 설계, 구현, 테스트, 유지보수라는 단어가 등장합니다. \n선형 순차적 모델은 각 단계가 직선적으로 순차적으로 진행된다는 것을 의미합니다. \n이는 각 단계가 끝나기 전까지 다음 단계로 넘어가지 않는다는 것을 의미하며 이러한 특징은 폭포수 모형의 특징입니다. \n따라서 정답은 3번 폭포수 모형입니다. \n폭포수 모형은 가장 일반적인 소프트웨어 개발 모형 중 하나로 소프트웨어 개발의 각 단계를 순차적으로 진행하는 모델입니다. \n각 단계는 직선적으로 진행되며, 이전 단계가 완료될 때까지 다음 단계로 넘어가지 않습니다. \n이러한 모델은 개발 과정에서 발생할 수 있는 오류나 문제를早期에 обнаруж하고 수정할 수 있습니다. \n하지만 각 단계가 순차적으로 진행되므로 개발期間이 길어질 수 있습니다.</p>"]}},{"id":"13772","number":94,"category":"정보시스템 구축관리","type":"choice","subject":"스트림 암호화 방식의 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"비트/바이트/단어들을 순차적으로 암호화한다."},{"n":2,"html":"해쉬 함수를 이용한 해쉬 암호화 방식을 사용한다."},{"n":3,"html":"RC4는 스트림 암호화 방식에 해당한다."},{"n":4,"html":"대칭키 암호화 방식이다."}],"answer":[2],"wiki":[{"title":"암호","url":"https://itwiki.kr/w/암호"}],"explain":{"ai":["<p>스트림 암호화 방식은 데이터를 비트 또는 바이트 단위로 순차적으로 암호화하는 방식을 말한다. 스트림 암호화는 대칭키 암호화 방식을 사용한다. RC4는 스트림 암호화 방식의 대표적인 예시 중 하나다. 스트림 암호화 방식은 순차적으로 데이터를 암호화하기 때문에 빠른 처리 속도가 특징이다.</p>\n<p>스트림 암호화 방식의 설명으로 옳지 않은 것은 해쉬 함수를 이용한 해쉬 암호화 방식을 사용한다는 것이다. 해쉬 함수는 데이터의完整성과 진위를 확인하는 데 사용되며, 암호화 키를 사용하여 데이터를 암호화하는 기능은 없다. 따라서 스트림 암호화 방식의 설명으로는 적절하지 않다.</p>"]}},{"id":"13773","number":95,"category":"정보시스템 구축관리","type":"choice","subject":"세션 하이재킹을 탐지하는 방법으로 거리가 먼 것은?","choices":[{"n":1,"html":"FTP SYN SEGNENT 탐지"},{"n":2,"html":"비동기화 상태 탐지"},{"n":3,"html":"ACK STORM 탐지"},{"n":4,"html":"패킷의 유실 및 재전송 증가 탐지"}],"answer":[1],"wiki":[{"title":"세션 하이재킹","url":"https://itwiki.kr/w/세션 하이재킹"}],"explain":{"ai":["<p>세션 하이재킹은 공격자가 유효한 사용자와 서버 간의 세션을 가로채어 불법적으로 접근하는 공격입니다. 이를 탐지하기 위해 비동기화 상태 탐지, ACK 스톰 탐지, 패킷 유실 및 재전송 증가 탐지 등의 방법을 사용합니다.</p>\n<p>비동기화 상태 탐지란 공격자가 세션을 가로채면 사용자와 서버 간의 통신이 비동기화 상태가 될 가능성이 높다는 점을 이용한 방법입니다. ACK 스톰 탐지는 공격자가 세션을 가로채면 ACK 패킷이 과도하게 증가할 수 있다는 점을 이용한 방법입니다. 패킷 유실 및 재전송 증가 탐지란 공격자가 세션을 가로채면 패킷이 유실되거나 재전송되는 경우가 늘어날 수 있다는 점을 이용한 방법입니다.</p>\n<p>한편 FTP SYN 세그먼트 탐지는 세션 하이재킹과는 관련이 없는 방법입니다. FTP SYN 세그먼트는 파일 전송 프로토콜에서 사용되는 SYN 패킷과 관련이 있습니다. 따라서 세션 하이재킹을 탐지하는 방법으로는 FTP SYN 세그먼트 탐지가 적절하지 않습니다.</p>"]}},{"id":"13774","number":96,"category":"정보시스템 구축관리","type":"choice","subject":"소프트웨어공학에 대한 설명으로 거리가 먼 것은?","choices":[{"n":1,"html":"소프트웨어공학이란 소프트웨어의 개발, 운용, 유지보수 및 파기에 대한 체계적인 접근 방법이다."},{"n":2,"html":"소프트웨어공학은 소프트웨어 제품의 품질을 향상시키고 소프트웨어 생산성과 작업 만족도를 증대시키는 것이 목적이다."},{"n":3,"html":"소프트웨어공학의 궁극적 목표는 최대의 비용으로 계획된 일정보다 가능한 빠른 시일 내에 소프트웨어를 개발하는 것이다."},{"n":4,"html":"소프트웨어공학은 신뢰성 있는 소프트웨어를 경제적인 비용으로 획득하기 위해 공학적 원리를 정립하고 이를 이용하는 것이다."}],"answer":[3],"wiki":[{"title":"소프트웨어 위기","url":"https://itwiki.kr/w/소프트웨어 위기"}],"explain":{"ai":["<p>소프트웨어공학은 체계적인 접근 방법을 통해 소프트웨어 개발, 운용, 유지보수, 파기를 효율적으로 관리하는 것이 목표다. 이를 통해 소프트웨어의 품질을 향상시키고 생산성, 작업 만족도를 높이는데 목표가 있다. 또한 신뢰성 있는 소프트웨어를 경제적인 비용으로 개발하는 것이 궁극적 목표다. </p>\n<p>소프트웨어공학의 목표는 소프트웨어의 개발 기간을 단축하고, 비용을 절감하며, 품질을 향상시키는 데에 있다. 그러나 3번은 최대의 비용으로 가능한 빠른 시일 내에 개발하는 것이 목표라고 하며, 이는 소프트웨어공학의 목표와 거리가 먼 설명이다. 소프트웨어공학은 경제적인 비용으로 개발하는 것을 목표로 하며, 최대의 비용이 아님을 강조할 필요가 있다.</p>"]}},{"id":"13775","number":97,"category":"정보시스템 구축관리","type":"choice","subject":"소프트웨어 개발 방법론 중 CBD(Component Based Development)에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"생산성과 품질을 높이고, 유지보수 비용을 최소화할 수 있다."},{"n":2,"html":"컴포넌트 제작 기법을 통해 재사용성을 향상시킨다."},{"n":3,"html":"모듈의 분할과 정복에 의한 하향식 설계방식이다."},{"n":4,"html":"독립적인 컴포넌트 단위의 관리로 복잡성을 최소화할 수 있다."}],"answer":[3],"explain":{"ai":["<p>소프트웨어 개발 방법론 중 CBD란 컴포넌트 기반 개발을 의미한다. CBD는 컴포넌트를 단위로 개발하여 시스템을 구축하는 방식이다. CBD의 주요 특징은 생산성과 품질을 높이고 유지보수 비용을 최소화할 수 있으며, 컴포넌트 제작 기법을 통해 재사용성을 향상시킨다. 또한 독립적인 컴포넌트 단위의 관리로 복잡성을 최소화할 수 있다. </p>\n<p>그러나 모듈의 분할과 정복에 의한 하향식 설계방식은 CBD의 특징이 아니다. CBD는 컴포넌트를 중점으로 개발하는 방식으로, 재사용성과 유연성을 강조한다. 따라서 CBD는 상향식 설계방식에 가깝다. </p>\n<p>따라서 정답은 3번인 모듈의 분할과 정복에 의한 하향식 설계방식이다. 이는 CBD의 기본 원리와 다르기 때문이다.</p>"]}},{"id":"13776","number":98,"category":"정보시스템 구축관리","type":"choice","subject":"정보 보안의 3요소에 해당하지 않는 것은?","choices":[{"n":1,"html":"기밀성"},{"n":2,"html":"무결성"},{"n":3,"html":"가용성"},{"n":4,"html":"휘발성"}],"answer":[4],"wiki":[{"title":"보안","url":"https://itwiki.kr/w/보안"},{"title":"CIA","url":"https://itwiki.kr/w/CIA"}],"explain":{"ai":["<p>정보 보안의 3요소는 기밀성, 무결성, 가용성이다. \n기밀성은 권한이 있는 사람만 정보에 접근할 수 있도록 정보를 보호하는 것을 말한다. \n무결성은 정보가 변경되거나 파내여지지 않도록 보호하는 것을 말한다. \n가용성은 정보가 언제나 필요한 사용자가 접근할 수 있도록 정보를 보호하는 것을 말한다. \n그러나 휘발성은 정보 보안의 3요소에 해당하지 않는다. \n정보 보안의 3요소에 해당하지 않는 휘발성은 컴퓨터 시스템의 임의 접근 메모리 등을 의미한다. 정보를 보호하는 3요소에는 해당하지 않는다.</p>"]}},{"id":"13777","number":99,"category":"정보시스템 구축관리","type":"choice","subject":"소셜 네트워크에서 악의적인 사용자가 지인 또는 특정 유명인으로 가장하여 활동하는 공격 기법은?(문제 오류로 가답안 발표시 1번으로 발표되었지만 확정답안 발표시 1, 2번이 정답처리 되었습니다. 여기서는 가답안인 1번을 누르시면 정답 처리 됩니다.)","choices":[{"n":1,"html":"Evil Twin Attack"},{"n":2,"html":"Phishing"},{"n":3,"html":"Logic Bomb"},{"n":4,"html":"Cyberbullying"}],"answer":[1],"explain":{"ai":["<p>소셜 네트워크에서 악의적인 사용자가 지인 또는 특정 유명인으로 가장하여 활동하는 공격 기법은 Evil Twin Attack라고 불린다. 이 공격 기법은 사용자의 신뢰를 얻기 위해 타인의身份를 도용하여 불법적인 활동을 하는 것을 말한다. 악의적인 사용자는 도용한身份를 이용해 사용자의 개인 정보를 탈취하거나 금융 정보를 취득하기도 한다. 따라서 소셜 네트워크를 이용할 때에는 타인의 身分을 확인하는 것이 중요하며 개인 정보를 주의해서 관리해야 한다. 이러한 공격 기법은 인터넷 사용자들에게 큰 위협을 줄 수 있으므로 주의가 필요하다.</p>"]}},{"id":"13778","number":100,"category":"정보시스템 구축관리","type":"choice","subject":"공개키 암호에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"10명이 공개키 암호를 사용할 경우 5개의 키가 필요하다."},{"n":2,"html":"복호화키는 비공개 되어 있다."},{"n":3,"html":"송신자는 수신자의 공개키로 문서를 암호화한다."},{"n":4,"html":"공개키 암호로 널리 알려진 알고리즘은 RSA가 있다."}],"answer":[1],"wiki":[{"title":"공개키 암호","url":"https://itwiki.kr/w/공개키 암호"}],"explain":{"ai":["<p>정답은 1번입니다. 공개키 암호시스템에서 각 사용자는 자신의 공개키와 개인키 한 쌍을 갖습니다. 따라서 10명이 사용할 경우, 각 사람마다 독립적인 키 쌍이 필요하므로 총 10개의 키 쌍, 즉 20개의 키를 갖게 됩니다(각 사람당 공개키 1개와 개인키 1개). 따라서 10명이 사용하려면 5개의 키만 필요하다는 설명은 틀렸습니다. 나머지 보기들은 모두 공개키 암호의 정확한 특징을 설명하고 있습니다: 복호화는 개인키로 이루어지므로 개인키는 비공개여야 하고, 실제로 송신자는 수신자의 공개키를 이용해 데이터를 암호화하며, RSA는 공개키 암호화 알고리즘의 대표적인 예입니다.</p>"]}}]};